function computeDerived() {
  const sp = state.character.special;
  const trait = state.character.trait;
  const level = state.player.level || 1;
  const settlementBonus = (state.settlements?.marseille || 0) * 2;
  const armor = currentArmor ? currentArmor() : ARMORS?.vaultSuit;
  state.player.maxHp = 85 + sp.E * 10 + (level - 1) * 4 + settlementBonus + ((state.perks?.armorer||0)*2);
  state.player.maxAp = 65 + sp.A * 10 + (trait === 'mistral' ? 10 : 0);
  state.player.hp = clamp(state.player.hp, 1, state.player.maxHp);
  state.player.ap = clamp(state.player.ap, 0, state.player.maxAp);
  state.player.damageResistance = armor?.dr || 0;
  state.player.radResistance = armor?.rad || 0;
}

function saveGame(manual = false) {
  if (!gameStarted) return false;
  persistAmmoCache();
  state.version = VERSION;
  state.lastSave = new Date().toISOString();
  try {
    storage.setItem(SAVE_KEY, JSON.stringify(state));
    updateContinueButton();
    if (manual) toast('Partie sauvegardée.', 'good');
    return true;
  } catch (e) {
    if (manual) toast('Échec de la sauvegarde locale.', 'bad');
    else console.warn('Sauvegarde locale indisponible dans ce contexte.', e);
    return false;
  }
}
function hasSave() {
  try {
    if (storage.getItem(SAVE_KEY)) return true;
    return LEGACY_SAVE_KEYS.some(key => !!storage.getItem(key));
  } catch { return false; }
}
function loadGame() {
  try {
    let raw = storage.getItem(SAVE_KEY);
    let legacyKey = null;
    if (!raw) {
      legacyKey = LEGACY_SAVE_KEYS.find(key => storage.getItem(key));
      if (legacyKey) raw = storage.getItem(legacyKey);
    }
    if (!raw) return false;
    const parsed = JSON.parse(raw);
    state = migrateState(parsed);
    syncEquipment();
    gameStarted = true;
    loadZone(state.player.zone || 'vault', { spawn: state.player.pos, yaw: state.player.yaw, silent: false });
    if (legacyKey) { saveGame(false); toast('Sauvegarde antérieure migrée vers la v0.14.', 'good'); }
    else toast('Sauvegarde chargée.', 'good');
    return true;
  } catch (e) {
    console.error(e);
    toast('La sauvegarde est illisible.', 'bad');
    return false;
  }
}
function migrateState(old) {
  const fresh = baseState();
  const merged = { ...fresh, ...old };
  merged.character = { ...fresh.character, ...(old.character || {}), special: { ...fresh.character.special, ...((old.character || {}).special || {}) } };
  merged.player = { ...fresh.player, ...(old.player || {}) };
  merged.quest = { ...fresh.quest, ...(old.quest || {}) };
  merged.side = { ...fresh.side, ...(old.side || {}) };
  merged.flags = { ...fresh.flags, ...(old.flags || {}) };
  merged.flags.enemyDead = { ...fresh.flags.enemyDead, ...((old.flags || {}).enemyDead || {}) };
  merged.flags.looted = { ...fresh.flags.looted, ...((old.flags || {}).looted || {}) };
  merged.flags.notes = { ...fresh.flags.notes, ...((old.flags || {}).notes || {}) };
  merged.flags.doors = { ...fresh.flags.doors, ...((old.flags || {}).doors || {}) };
  merged.flags.worldChanges = { ...fresh.flags.worldChanges, ...((old.flags || {}).worldChanges || {}) };
  merged.flags.shelterResolved = { ...(fresh.flags.shelterResolved||{}), ...(((old.flags||{}).shelterResolved)||{}) };
  merged.flags.shelterOutcomes = { ...(fresh.flags.shelterOutcomes||{}), ...(((old.flags||{}).shelterOutcomes)||{}) };
  merged.flags.enemySeen = { ...(fresh.flags.enemySeen||{}), ...(((old.flags||{}).enemySeen)||{}) };
  merged.inventory = { ...fresh.inventory, ...(old.inventory || {}) };
  merged.ammo = { ...fresh.ammo, ...(old.ammo || {}) };
  if (!old.ammo) merged.ammo.ammo10 = Math.max(0, old.player?.ammoReserve ?? fresh.ammo.ammo10);
  merged.perks = { ...fresh.perks, ...(old.perks || {}) };
  merged.settlements = { ...fresh.settlements, ...(old.settlements || {}) };
  merged.economy = { ...fresh.economy, ...(old.economy || {}) };
  merged.economy.merchants = { ...fresh.economy.merchants, ...((old.economy || {}).merchants || {}) };
  merged.economy.contracts = { ...fresh.economy.contracts, ...((old.economy || {}).contracts || {}) };
  merged.events = { ...fresh.events, ...(old.events || {}) };
  merged.events.history = Array.isArray((old.events||{}).history) ? old.events.history : [];
  merged.weather = { ...fresh.weather, ...(old.weather || {}) };
  merged.rep = { ...fresh.rep, ...(old.rep || {}) };
  merged.equipment = { ...fresh.equipment, ...(old.equipment || {}) };
  merged.equipment.ownedWeapons = Array.from(new Set([...(fresh.equipment.ownedWeapons||[]), ...(((old.equipment||{}).ownedWeapons)||[])]));
  merged.equipment.ownedArmors = Array.from(new Set([...(fresh.equipment.ownedArmors||[]), ...(((old.equipment||{}).ownedArmors)||[])]));
  merged.equipment.weaponCondition = { ...fresh.equipment.weaponCondition, ...(((old.equipment||{}).weaponCondition)||{}) };
  merged.equipment.armorCondition = { ...fresh.equipment.armorCondition, ...(((old.equipment||{}).armorCondition)||{}) };
  merged.equipment.loadedAmmo = { ...fresh.equipment.loadedAmmo, ...(((old.equipment||{}).loadedAmmo)||{}) };
  merged.equipment.weaponMods = { ...fresh.equipment.weaponMods, ...(((old.equipment||{}).weaponMods)||{}) };
  if (!(old.equipment||{}).loadedAmmo && old.player?.weaponId) merged.equipment.loadedAmmo[old.player.weaponId] = clamp(old.player.ammoClip ?? 0, 0, (WEAPONS[old.player.weaponId]||WEAPONS.pistol10).clip);
  merged.companions = { ...fresh.companions, ...(old.companions || {}), loyalty: { ...fresh.companions.loyalty, ...(((old.companions||{}).loyalty)||{}) } };
  merged.crime = { ...fresh.crime, ...(old.crime || {}) };
  merged.status = { ...fresh.status, ...(old.status || {}) };
  merged.vehicle = { ...fresh.vehicle, ...(old.vehicle || {}) };
  if (merged.flags.skiffUnlocked) merged.vehicle.skiffUnlocked = true;
  if(!merged.player.weaponId) merged.player.weaponId = 'pistol10';
  if(!merged.player.armorId) merged.player.armorId = 'vaultSuit';
  merged.achievements = Array.isArray(old.achievements) ? old.achievements : [];
  if (!merged.player.activeCompanion && merged.flags.mireilleRecruited) merged.player.activeCompanion = 'mireille';
  if (merged.quest.mainComplete && merged.quest.main === 11 && !merged.flags.routeChapterStarted) merged.quest.main = 11;
  merged.version = VERSION;
  return merged;
}
function updateContinueButton() { $('btnContinue').disabled = !hasSave(); }

function toast(text, type = '') {
  const el = document.createElement('div');
  el.className = `toast ${type}`;
  el.textContent = text;
  $('toastStack').appendChild(el);
  setTimeout(() => { el.style.opacity = '0'; el.style.transform = 'translateX(20px)'; }, 3200);
  setTimeout(() => el.remove(), 3700);
}
function subtitle(speaker, text, duration = 3600) {
  if (!settings.subtitles) return;
  const el = $('subtitle');
  el.innerHTML = `<b>${speaker}</b>${text}`;
  el.classList.remove('hidden');
  clearTimeout(subtitle.timer);
  subtitle.timer = setTimeout(() => el.classList.add('hidden'), duration);
}
function achievement(id, title) {
  if (state.achievements.includes(id)) return;
  state.achievements.push(id);
  toast(`Succès débloqué — ${title}`, 'good');
  audio.ui(720, 0.16);
}
function repChange(faction, amount) {
  state.rep[faction] = (state.rep[faction] || 0) + amount;
  const labels = { ligue: 'Ligue des Communes', rade: 'Commune de la Rade', arsenal: 'Arsenal de La Ciotat', continuite: 'Direction de la Continuité', veilleurs: 'Veilleurs de la Garde', francs: 'Francs du Large', rails:'Collectif des cheminots', collines:'Communes des Collines', marches:'Marchés libres', eaux:'Service des eaux', artisans:'Artisans de l’Argile', secours:'Réseau des Vigies' };
  toast(`${labels[faction] || faction} : ${amount > 0 ? '+' : ''}${amount}`, amount >= 0 ? 'good' : 'bad');
}
function addItem(id, amount = 1, label = null) {
  if(isAmmo(id)){addAmmo(id,amount,label);return}
  state.inventory[id] = (state.inventory[id] || 0) + amount;
  toast(`${label || itemLabel(id)} ×${amount}`, 'good');
  audio.ui(540, .08);
}
function removeItem(id, amount = 1) {
  if ((state.inventory[id] || 0) < amount) return false;
  state.inventory[id] -= amount;
  return true;
}
