function difficultyInfo(){return({story:{incoming:.65,outgoing:1.2,loot:1.2,label:'Histoire'},survivor:{incoming:1,outgoing:1,loot:1,label:'Survie'},hardcore:{incoming:1.45,outgoing:.88,loot:.8,label:'Sans pitié'}})[settings.difficulty]||{incoming:1,outgoing:1,loot:1,label:'Survie'}}
function currentWeapon(){
  const base=WEAPONS[state.player.weaponId]||WEAPONS.pistol10,mod=state.equipment?.weaponMods?.[state.player.weaponId]?WEAPON_MODS[state.player.weaponId]:null;
  if(!mod)return base;
  return {...base,damage:base.damage*(mod.damageMult||1),spread:base.spread*(mod.spreadMult||1),conditionLoss:base.conditionLoss*(mod.conditionMult||1),reload:base.reload*(mod.reloadMult||1)};
}
function currentArmor(){return ARMORS[state.player.armorId]||ARMORS.vaultSuit}
function ammoIdFor(weapon=currentWeapon()){return weapon.melee?null:(weapon.ammoId||'ammo10')}
function isAmmo(id){return !!AMMO_INFO[id]}
function ammoAmount(id){return Math.max(0,state.ammo?.[id]||0)}
function addAmmo(id,amount=1,label=null){if(!isAmmo(id))return;state.ammo[id]=(state.ammo[id]||0)+amount;if(ammoIdFor()===id)state.player.ammoReserve=state.ammo[id];toast(`${label||AMMO_INFO[id].name} ×${amount}`,'good');audio.ui(540,.08)}
function persistAmmoCache(){if(!state?.equipment||!state?.player||!state?.ammo)return;const id=state.player.weaponId||'pistol10',w=WEAPONS[id]||WEAPONS.pistol10;if(w.melee){state.equipment.loadedAmmo[id]=1;return}state.equipment.loadedAmmo[id]=clamp(state.player.ammoClip??0,0,w.clip);state.ammo[w.ammoId||'ammo10']=Math.max(0,state.player.ammoReserve??0)}
function equipmentCondition(type,id){const bucket=type==='weapon'?state.equipment.weaponCondition:state.equipment.armorCondition;return clamp(bucket[id]??100,0,100)}
function setEquipmentCondition(type,id,value){const bucket=type==='weapon'?state.equipment.weaponCondition:state.equipment.armorCondition;bucket[id]=clamp(value,0,100)}
function syncEquipment(){
  const w=currentWeapon(),id=state.player.weaponId;
  state.player.weapon=w.name;state.player.clipSize=w.melee?1:w.clip;
  if(w.melee){state.player.ammoClip=1;state.player.ammoReserve=0}else{state.player.ammoClip=clamp(state.equipment.loadedAmmo?.[id]??state.player.ammoClip??0,0,w.clip);state.player.ammoReserve=ammoAmount(ammoIdFor(w));}
  computeDerived();
}
function addOwnedEquipment(id){if(WEAPONS[id]){if(!state.equipment.ownedWeapons.includes(id))state.equipment.ownedWeapons.push(id);if(state.equipment.weaponCondition[id]==null)state.equipment.weaponCondition[id]=100;if(state.equipment.loadedAmmo[id]==null)state.equipment.loadedAmmo[id]=WEAPONS[id].melee?1:0;toast(`${WEAPONS[id].name} ajouté à l’équipement.`,'good');return true}if(ARMORS[id]){if(!state.equipment.ownedArmors.includes(id))state.equipment.ownedArmors.push(id);if(state.equipment.armorCondition[id]==null)state.equipment.armorCondition[id]=100;toast(`${ARMORS[id].name} ajoutée à l’équipement.`,'good');return true}return false}
function equipWeapon(id){if(!state.equipment.ownedWeapons.includes(id)||!WEAPONS[id])return;persistAmmoCache();state.player.weaponId=id;syncEquipment();audio.ui(580,.08);renderPipboy();saveGame(false)}
function installWeaponMod(id){const mod=WEAPON_MODS[id];if(!mod||!state.equipment.ownedWeapons.includes(id))return;if(state.equipment.weaponMods[id]){toast('Cette modification est déjà installée.');return}if(!payCost(mod.cost)){toast(`Ressources requises : ${costText(mod.cost)}`,'bad');return}state.equipment.weaponMods[id]=true;gainXP(25,'Modification d’arme');audio.success();toast(`${mod.name} installé.`,'good');syncEquipment();renderPipboy();saveGame(false)}
function equipArmor(id){if(!state.equipment.ownedArmors.includes(id)||!ARMORS[id])return;state.player.armorId=id;computeDerived();audio.ui(510,.08);renderPipboy();saveGame(false)}
function repairEquipment(kind){const id=kind==='weapon'?state.player.weaponId:state.player.armorId,condition=equipmentCondition(kind,id),perk=state.perks.armorer||0,cost=Math.max(1,Math.ceil((100-condition)/22)*(kind==='weapon'?2:3)-perk);if(condition>=99){toast('Équipement déjà en parfait état.');return}if((state.inventory.weaponParts||0)<cost){toast(`Pièces d’arme requises : ${cost}.`,'bad');return}state.inventory.weaponParts-=cost;setEquipmentCondition(kind,id,Math.min(100,condition+45+perk*10));gainXP(10,'Réparation');toast(`${kind==='weapon'?'Arme':'Armure'} réparée.`,'good');renderPipboy();saveGame(false)}

