function xpNeeded(level=state.player.level||1){return 90+level*45}
function gainXP(amount,label='Progression'){
  if(amount<=0)return;state.player.xp=(state.player.xp||0)+amount;toast(`${label} · +${amount} XP`,'good');
  let need=xpNeeded();
  while(state.player.xp>=need){state.player.xp-=need;state.player.level=(state.player.level||1)+1;state.player.perkPoints=(state.player.perkPoints||0)+1;computeDerived();state.player.hp=state.player.maxHp;state.player.ap=state.player.maxAp;achievement(`level-${state.player.level}`,`Niveau ${state.player.level}`);need=xpNeeded()}
}
function buyPerk(id){const info=PERK_INFO[id],rank=state.perks[id]||0;if(!info||rank>=info.max){toast('Rang maximal atteint.');return}if((state.player.perkPoints||0)<1){toast('Aucun point d’avantage disponible.','bad');return}state.player.perkPoints--;state.perks[id]=rank+1;audio.success();toast(`${info.name} · rang ${rank+1}`,'good');saveGame(false);renderPipboy()}
function companionAvailable(id){const d=COMPANIONS[id];return !!(d&&state.flags[d.flag])}
function companionLoyalty(id){return clamp(state.companions?.loyalty?.[id]||0,0,100)}
function changeLoyalty(id,amount,reason=''){if(!state.companions)state.companions={loyalty:{}};state.companions.loyalty[id]=clamp(companionLoyalty(id)+amount,0,100);toast(`${COMPANIONS[id]?.name||id} · loyauté ${amount>=0?'+':''}${amount}${reason?` · ${reason}`:''}`,amount>=0?'good':'bad')}
function activeCompanion(){const id=state.player.activeCompanion;return companionAvailable(id)?{id,...COMPANIONS[id],loyalty:companionLoyalty(id)}:null}
function chooseCompanion(id){if(id===null){state.player.activeCompanion=null;refreshWorld();renderPipboy();saveGame(false);toast('Vous voyagez désormais seul.');return}if(!companionAvailable(id)){toast('Ce compagnon n’est pas encore recruté.','bad');return}state.player.activeCompanion=id;refreshWorld();toast(`${COMPANIONS[id].name} rejoint l’escouade.`,'good');renderPipboy();saveGame(false)}
function costText(cost){return Object.entries(cost).map(([k,v])=>`${itemLabel(k)==='caps'? 'Capsules':itemLabel(k)} ${v}`).join(' · ')}
function hasCost(cost){return Object.entries(cost).every(([k,v])=>k==='caps'?(state.player.caps||0)>=v:(state.inventory[k]||0)>=v)}
function payCost(cost){if(!hasCost(cost))return false;for(const [k,v] of Object.entries(cost)){if(k==='caps')state.player.caps-=v;else state.inventory[k]-=v}return true}
function addResource(id,amount=1,label=null){state.inventory[id]=(state.inventory[id]||0)+amount;toast(`${label||itemLabel(id)} ×${amount}`,'good')}
function craft(id,cost,amount=1){
  const discount=Math.min(0.3,(state.perks.technician||0)*.1);const adjusted={};for(const [k,v] of Object.entries(cost))adjusted[k]=k==='caps'?v:Math.max(1,Math.ceil(v*(1-discount)));
  if(!payCost(adjusted)){toast(`Composants requis : ${costText(adjusted)}`,'bad');return false}
  if(isAmmo(id))addAmmo(id,amount);else addItem(id,amount);gainXP(8,'Fabrication');saveGame(false);return true
}
function upgradeSettlement(id){const info=SETTLEMENT_INFO[id],level=state.settlements[id]||0;if(!info||level>=3){toast('Installation au rang maximal.');return}const cost=info.costs[level];if(!payCost(cost)){toast(`Ressources requises : ${costText(cost)}`,'bad');return}state.settlements[id]=level+1;gainXP(25+level*10,info.name);audio.success();toast(`${info.name} amélioré au rang ${level+1}.`,'good');computeDerived();saveGame(false);renderPipboy()}
function grantNetworkProduction(){
  const s=state.settlements;let messages=[];
  const ammo=(s.aubagne||0)*3+(s.laciotat||0)*2;if(ammo){state.ammo.ammo10+=ammo;messages.push(`${ammo} munitions 10 mm`)}
  const rivets=(s.drydock||0)*4+(s.hull27||0)*2;if(rivets){state.ammo.rivets+=rivets;messages.push(`${rivets} rivets`)}
  const shells=(s.ciotatport||0)*2;if(shells){state.ammo.shells+=shells;messages.push(`${shells} cartouches`)}
  const cells=(s.hull27||0)*2;if(cells){state.ammo.cells+=cells;messages.push(`${cells} cellules`)}
  const scrap=(s.gemenos||0)+(s.huveaune||0)+(s.drydock||0);if(scrap){state.inventory.scrap+=scrap;messages.push(`${scrap} ferraille`)}
  const food=(s.garlaban||0)+(s.cassis||0)+(s.ileverte||0);if(food){state.inventory.food+=food;messages.push(`${food} vivres`)}
  const water=(s.ceyreste||0)+(s.fontdemai||0)+(s.longchamp||0)*2+(s.mugel||0);if(water&&state.inventory.water<22){state.inventory.water+=water;messages.push(`${water} eau filtrée`)}
  const marketCaps=(s.panier||0)*3+(s.ciotatport||0)*2+(s.canebiere||0)*3+(s.cinema||0);if(marketCaps){state.player.caps+=marketCaps;messages.push(`${marketCaps} capsules du commerce`)}
  const urbanAmmo=(s.saintcharles||0)*2+(s.tunnels||0)*2;if(urbanAmmo){state.ammo.ammo10+=urbanAmmo;messages.push(`${urbanAmmo} munitions ferroviaires`)}
  const archiveCloth=(s.cinema||0);if(archiveCloth){state.inventory.cloth+=archiveCloth;messages.push(`${archiveCloth} tissu d’archive`)}
  const ceramic=(s.ceramiques||0)+((s.aubagnehaute||0)>0?(state.perks.ceramist||0):0);if(ceramic){state.inventory.clay=(state.inventory.clay||0)+ceramic;messages.push(`${ceramic} argile réfractaire`)}
  const firewatch=(s.garlabanpass||0);if(firewatch>=2&&state.inventory.flare<6){state.inventory.flare++;messages.push('1 fusée de vigie')}if(firewatch>=3&&state.inventory.fireGel<4){state.inventory.fireGel++;messages.push('1 gel coupe-feu')}
  const gardeCare=(s.lagarde||0);if(gardeCare>=2&&state.inventory.stimpak<10){state.inventory.stimpak++;messages.push('1 Stimpak des Veilleurs')}if(gardeCare>=3&&state.inventory.antibiotics<6){state.inventory.antibiotics++;messages.push('1 antibiotique')}
  if((s.marseille||0)>=2&&state.inventory.stimpak<8){state.inventory.stimpak++;messages.push('1 Stimpak')}
  if((s.drydock||0)>=2){state.inventory.steelPlate=(state.inventory.steelPlate||0)+1;messages.push('1 plaque navale')}
  if((s.mugel||0)>=2&&state.inventory.fuelCell<6){state.inventory.fuelCell++;messages.push('1 carburant marin')}
  if((s.latreille||0)>=2&&!state.flags.notes['regional-bulletin'])state.flags.notes['regional-bulletin']=true
  if(ammoIdFor())state.player.ammoReserve=ammoAmount(ammoIdFor());
  if(messages.length)toast(`Production du réseau : ${messages.join(', ')}.`,'good')
}


