const DETAIL_VIGNETTES={
  vault:['Casier de nuit','Une paire de bottes est soigneusement alignée sous le lit. Le propriétaire a noté chaque ressemelage : même sous terre, les objets ont une histoire avant de devenir de la ferraille.'],
  aubagne:['Linge des ateliers','Des vêtements réparés avec des morceaux de combinaisons techniques sèchent au mistral. Les coutures indiquent plusieurs générations de propriétaires.'],
  marseille:['Cordage de la Rade','Les nœuds du quai mêlent techniques de pêche, de remorquage et de contrebande. Chaque équipage laisse une ligature différente.'],
  laciotat:['Établi du quart de nuit','Une tasse, un masque de soudure et trois pièces refusées racontent une relève interrompue au milieu de son travail.'],
  huveaune:['Signal réemployé','Le vieux signal ferroviaire sert maintenant à prévenir les caravanes des crues et des pillards. Trois couleurs, trois dangers.'],
  garlaban:['Camp des herboristes','Des sachets de thym, de romarin et de plantes mutées sont suspendus loin du feu. Les cueilleurs ont appris à séparer remède et poison.'],
  gemenos:['Palette des Paluds','Chaque caisse porte deux marques : celle de l’atelier qui l’a produite et celle de la commune qui doit la recevoir. La confiance tient parfois à un tampon.'],
  cassis:['Filet réparé','Le filet contient des fibres de voile, du câble électrique et des cheveux tressés. Rien n’est jeté lorsque la mer décide du prochain repas.'],
  calanques:['Nécessaire de secours','Une trousse a été remplie par plusieurs mains : bandages propres, corde brûlée, fusée humide et une liste de personnes revenues.'],
  ceyreste:['Auge commune','Des encoches mesurent la part d’eau de chaque famille. Les plus anciennes ont été corrigées sans jamais être effacées.'],
  latreille:['Pierres nommées','Sous chaque plaque officielle, un nom a été gravé à la main. Les habitants savent que les archives peuvent brûler ; la pierre, moins facilement.'],
  fontdemai:['Établi de taille','Les outils sont rangés par saison plutôt que par fonction. Le domaine travaille au rythme de l’eau, pas à celui des anciens calendriers.'],
  panier:['Étagère des remèdes','Les bocaux sont classés par symptômes compréhensibles plutôt que par anciens noms médicaux. La ville a réinventé sa propre pharmacopée.'],
  longchamp:['Codes de vannes','Des bandes de tissu coloré doublent les numéros illisibles. Même un enfant peut maintenant comprendre quelle conduite alimente son quartier.'],
  ciotatport:['Matériel de pêche partagé','Les flotteurs portent les initiales de plusieurs familles. Le matériel circule selon les marées et revient rarement au même quai.'],
  syndicat:['Casiers sans cadenas','Les ouvriers ont retiré les serrures après la crise de la Coque 27. Les outils restent personnels ; les preuves, elles, appartiennent à tous.'],
  drydock:['Poste de soudure','Le masque a été réparé avec une vitre de cinéma. À travers le verre teinté, la cale ressemble à une salle de projection industrielle.'],
  hull27:['Table de pause','Vingt-sept encoches ont été ajoutées sous le plateau. Aucune plaque officielle ne les mentionne, mais chaque équipe connaît leur signification.'],
  mugel:['Établi du skiff','Des pièces de trois bateaux différents maintiennent le M-12 en état. La réparation est devenue une généalogie mécanique.'],
  mer:['Bouée des absents','La bouée porte des rubans délavés. Les marins la contournent sans ordre écrit, laissant la mer conserver son mémorial.'],
  ileverte:['Tableau radio','Les horaires sont écrits à la craie pour pouvoir changer avec le vent. Une ligne reste toujours libre pour les appels sans indicatif.'],
  canebiere:['Café des passages','Les chaises ne sont jamais assorties. Les habitants les ont apportées depuis leurs anciens quartiers pour que personne ne s’assoie tout à fait chez un autre.'],
  cinema:['Bobines réparées','Les boîtes de film sont doublées de tissu et de métal. Les titres perdus ont été remplacés par les souvenirs des spectateurs.'],
  saintcharles:['Bagages sans départ','Certaines valises attendent depuis des années. Les cheminots refusent de les jeter tant qu’aucun registre ne confirme la mort de leurs propriétaires.'],
  tunnels:['Casier de maintenance','Les outils sont attachés par des ficelles de couleurs différentes. Dans la fumée, les équipes reconnaissent leur matériel au toucher.'],
  lagarde:['Lit de passage','Le cadre porte les signatures de patients repartis debout. Les Veilleurs disent qu’un lit doit conserver la preuve des guérisons, pas seulement celle des morts.'],
  aubagnehaute:['Balcon commun','Le linge de trois foyers partage la même corde. Les pinces portent des symboles simples pour éviter les disputes les jours de mistral.'],
  aubagnegare:['Chariot des évacués','Chaque valise possède une étiquette de destination et une seconde indiquant la personne chargée de la retrouver si son propriétaire disparaît.'],
  ceramiques:['Échantillons de cuisson','Les pots fissurés ne sont pas détruits : leurs cassures servent de manuel aux apprentis. Chaque défaut devient une leçon matérielle.'],
  huveaunesouterraine:['Poste de sécurité','Les équipes ont laissé des traits de craie à hauteur de main. Dans le noir, ils indiquent le chemin vers l’air le plus respirable.'],
  garlabanpass:['Journal des vigies','Les pages alternent relevés de vent, dessins d’animaux et messages aux équipes suivantes. Surveiller le feu signifie aussi apprendre le pays.']
};
const DETAIL_CACHE_REWARDS={aubagne:['scrap',2,'Boîte de pièces triées'],marseille:['cloth',2,'Toiles de quai'],huveaune:['circuitry',1,'Relais ferroviaire'],garlaban:['chemicals',2,'Herbes distillées'],gemenos:['weaponParts',1,'Pièces normalisées'],cassis:['food',2,'Réserve de pêche'],calanques:['flare',1,'Fusée sèche'],panier:['antibiotics',1,'Antibiotiques conservés'],drydock:['steelPlate',1,'Plaque marquée'],hull27:['rivets',12,'Rivets de la Coque 27'],mugel:['sealant',1,'Mastic marin'],canebiere:['caps',18,'Caisse de comptoir'],saintcharles:['ammo10',15,'Cartouches de sûreté'],ceramiques:['clay',2,'Argile testée'],garlabanpass:['fireGel',1,'Gel coupe-feu']};
function detailInspectionCount(){return Object.keys(state.flags.notes||{}).filter(k=>k.startsWith('detail-')).length}
function inspectWorldDetail(zone){const data=DETAIL_VIGNETTES[zone];if(!data)return;const key=`detail-${zone}`,fresh=!state.flags.notes[key];state.flags.notes[key]=true;DETAIL_NOTE_LABELS[key]=data[0];if(fresh){state.side.environment=(state.side.environment||0)+1;gainXP(10,'Observation du territoire');const count=detailInspectionCount();if(count===10)achievement('territory-eye','Œil du pays');if(count===20)achievement('daily-memory','Mémoire du quotidien');if(count===Object.keys(DETAIL_VIGNETTES).length)achievement('every-stone','Chaque pierre a un nom');toast(`Chroniques de terrain : ${count}/${Object.keys(DETAIL_VIGNETTES).length}`,'good')}openDialogue(speaker(data[0].toUpperCase(),'CHRONIQUE DE TERRAIN','OBS'),data[1],[{text:fresh?'Consigner cette trace.':'Relire la note.',onChoose:closeDialogue}]);saveGame(false)}
function findDetailVignetteSpot(w,pos){const baseY=pos[1]||detailGround(w,pos[0],pos[2],pos[1]||0);if(!detailBlocked(w,pos[0],pos[2],1.6,baseY))return[pos[0],baseY,pos[2]];const phase=(detailHash(`${w.id}-vignette-position`)%360)*Math.PI/180;for(const r of[4,6,8,10,12,15,18])for(let i=0;i<16;i++){const a=phase+i/16*TAU,cx=pos[0]+Math.sin(a)*r,cz=pos[2]+Math.cos(a)*r,cy=pos[1]||detailGround(w,cx,cz,baseY);if(cx<w.bounds[0]+2||cx>w.bounds[1]-2||cz<w.bounds[2]+2||cz>w.bounds[3]-2)continue;if(!detailBlocked(w,cx,cz,1.6,cy))return[cx,cy,cz]}return[pos[0],baseY,pos[2]]}
function addDetailVignette(w,plan){if(!plan?.v)return;const [type,pos,rot=0]=plan.v,spot=findDetailVignetteSpot(w,pos),x=spot[0],y=spot[1],z=spot[2];addDetailPreset(w,type,x,y,z,rot,1.05,detailRng(`${w.id}-vignette`));addInteract(w,`detail-${w.id}`,[x,y+1.1,z],`Observer : ${DETAIL_VIGNETTES[w.id]?.[0]||'trace du quotidien'}`,()=>inspectWorldDetail(w.id),{radius:3.8,kind:'detail',priority:.15});DETAIL_NOTE_LABELS[`detail-${w.id}`]=DETAIL_VIGNETTES[w.id]?.[0]||`Chronique de ${w.name}`;const reward=DETAIL_CACHE_REWARDS[w.id];if(reward){const item=reward[0],amount=reward[1],label=reward[2],p=detailPoint(x,z,rot,2.4,1.1);if(item==='caps'){if(!state.flags.looted[`detail-cache-${w.id}`])addInteract(w,`detail-cache-${w.id}`,[p[0],y+.5,p[1]],`Récupérer : ${label}`,()=>lootOnce(`detail-cache-${w.id}`,()=>{state.player.caps+=amount;toast(`${label} · +${amount} capsules`,'good')}));addCrate(w,p[0],p[1],COLORS.ochre)}else addLoot(w,`detail-cache-${w.id}`,[p[0],y+.1,p[1]],item,amount,label)}}
function addAmbientDetails(w,plan,rng){const themeSet=new Set(plan.themes||[]);if(themeSet.has('industrial')||themeSet.has('indoor')||themeSet.has('ceramic')){for(let i=0;i<(settings.quality==='low'?1:3);i++){const area=detailPick(rng,plan.areas),x=lerp(area[0],area[1],rng()),z=lerp(area[2],area[3],rng()),y=detailGround(w,x,z);if(!detailBlocked(w,x,z,1,y))w.ambient.push({type:'steam',base:[x,y,z],phase:rng()*TAU,scale:.7+rng()*.8})}}if(themeSet.has('maritime')||themeSet.has('sea'))w.ambient.push({type:'gulls',base:[0,8,0],phase:rng()*TAU,scale:1});if(themeSet.has('fire')){for(let i=0;i<3;i++){const area=detailPick(rng,plan.areas),x=lerp(area[0],area[1],rng()),z=lerp(area[2],area[3],rng()),y=detailGround(w,x,z);w.ambient.push({type:'embers',base:[x,y+.3,z],phase:rng()*TAU,scale:.7+rng()*.5})}}}
function applyEnvironmentalDetailPass(w){const plan=DETAIL_PLANS[w.id];if(!plan)return w;const rng=detailRng(`MISTRAL-v011-${w.id}`),quality=settings.quality==='low'?.48:settings.quality==='medium'?.75:1,target=Math.max(4,Math.round(plan.count*quality)),points=[];let placed=0,tries=0;while(placed<target&&tries<target*45){tries++;const area=detailPick(rng,plan.areas),x=lerp(area[0],area[1],rng()),z=lerp(area[2],area[3],rng()),y=w.id==='mer'?0:detailGround(w,x,z),pad=.9+rng()*1.1;if(w.id!=='mer'&&detailBlocked(w,x,z,pad,y))continue;if(points.some(p=>Math.hypot(p[0]-x,p[1]-z)<4.2))continue;const theme=detailPick(rng,plan.themes),type=detailPick(rng,DETAIL_THEME_POOLS[theme]||DETAIL_THEME_POOLS.urban),rot=rng()*TAU,s=.72+rng()*.52;addDetailPreset(w,type,x,y,z,rot,s,rng);points.push([x,z]);placed++}addDetailVignette(w,plan);addAmbientDetails(w,plan,rng);w.detailStats={clusters:placed,ambient:w.ambient.length,interactions:(w.interactables||[]).filter(it=>it.kind==='detail').length,drawsAdded:null};return w}
function ambientDetailParts(draws,a,t){const b=a.base||[0,0,0],s=a.scale||1,phase=a.phase||0;if(a.type==='steam'){for(let i=0;i<4;i++){const k=(t*.22+phase+i*.23)%1,x=b[0]+Math.sin(t*1.7+phase+i)*.24*s,z=b[2]+Math.cos(t*1.3+phase+i)*.18*s;part(draws,'sphere',[x,b[1]+.35+k*3.4*s,z],[.35*s*(1+k),.28*s*(1+k),.35*s*(1+k)],[.72,.74,.69],0,{alpha:(1-k)*.22})}}else if(a.type==='gulls'){for(let i=0;i<3;i++){const ang=t*.18+phase+i*TAU/3,r=24+i*7,x=b[0]+Math.sin(ang)*r,z=b[2]+Math.cos(ang)*r,y=b[1]+Math.sin(ang*2+i)*2.3;part(draws,'cube',[x,y,z],[.9,.05,.12],COLORS.white,-ang);part(draws,'cube',[x+Math.cos(ang)*.65,y,z-Math.sin(ang)*.65],[.9,.05,.12],COLORS.white,ang)}}else if(a.type==='embers'){for(let i=0;i<7;i++){const k=(t*.35+phase+i*.13)%1,x=b[0]+Math.sin(phase+i*2.1+k*4)*1.2*s,z=b[2]+Math.cos(phase+i*1.7+k*3)*.9*s;part(draws,'sphere',[x,b[1]+k*2.6*s,z],[.08*s,.12*s,.08*s],COLORS.amber,0,{emissive:.65,alpha:1-k})}}else if(a.type==='sparks'){for(let i=0;i<5;i++){const k=(t*.8+phase+i*.17)%1;part(draws,'sphere',[b[0]+Math.sin(i+phase)*k*.7,b[1]+k*.8,b[2]+Math.cos(i+phase)*k*.7],[.06,.06,.06],[.30,.72,.82],0,{emissive:.9,alpha:1-k})}}}


