function shelterCoreInteraction(id){const d=SHELTER_DEFS[id],done=state.flags.shelterResolved?.[id];if(done){openNote(`shelter-${id}`,`ABRI ${d.code} · ${d.title}`,`${d.experiment}\n\nDécision enregistrée : ${state.flags.shelterOutcomes[id]}.`);return}openDialogue(speaker(`NOYAU ${d.code}`,d.title.toUpperCase(),d.code),`${d.experiment} Le noyau peut être documenté, intégré au réseau ou démantelé.`,[
  {text:'Préserver les preuves et publier toutes les versions.',onChoose:()=>resolveShelter(id,'archives')},{text:'Intégrer les services survivants au réseau régional.',onChoose:()=>resolveShelter(id,'network')},{text:'Démanteler les systèmes dangereux et récupérer les pièces.',onChoose:()=>resolveShelter(id,'salvage')},{text:'Quitter le noyau.',onChoose:closeDialogue}
])}
function resolveShelter(id,outcome){const d=SHELTER_DEFS[id];state.flags.shelterResolved[id]=true;state.flags.shelterOutcomes[id]=outcome;state.flags.notes[`shelter-${id}`]=true;state.side.shelters=(state.side.shelters||0)+1;state.settlements[id]=Math.max(1,state.settlements[id]||0);if(outcome==='archives'){repChange('continuite',-1);repChange('collines',2);addResource('circuitry',2)}if(outcome==='network'){repChange('ligue',2);repChange('eaux',1);addResource('scrap',3)}if(outcome==='salvage'){addResource('scrap',7);addResource('weaponParts',3);state.player.caps+=55}addOwnedEquipment(d.reward);gainXP(120,`Abri ${d.code}`);const n=Object.keys(state.flags.shelterResolved).filter(k=>state.flags.shelterResolved[k]).length;if(n===1)achievement('first-shelter','Sous la Provence');if(n===4)achievement('half-shelters','Les quatre premières portes');if(n===8)achievement('eight-shelters','Huit expériences, huit mémoires');if(n===12)achievement('twelve-shelters','Les profondeurs répondent');if(n===18)achievement('eighteen-shelters','Dix-huit expériences consignées');if(n===24)achievement('twentyfour-shelters','Vingt-quatre portes sous la Provence');if(n===30)achievement('all-shelters','Trente expériences, une région');closeDialogue();refreshWorld();saveGame(false)}
function buildLoreShelter(id){const d=SHELTER_DEFS[id],w=createWorld(id,`Abri ${d.code} · ${d.title}`,d.region,{indoor:true,skyTop:[20,28,26],skyBottom:[31,38,34],fog:[.18,.23,.21],sunDir:[0,1,0],wind:0,daylight:.42});w.isShelter=true;w.bounds=[-58,58,-94,74];w.spawn=[0,1.65,64];w.spawnYaw=Math.PI;const col=d.palette,accent=d.accent;
  addFloorZone(w,0,-10,112,164,0,{priority:1,id:`${id}-floor`});addBox(w,[0,-.22,-10],[112,.44,164],cMix(col,COLORS.black,.22));addBox(w,[0,6.4,-10],[112,.35,164],[.09,.12,.11]);
  for(const [x,z,sx,sz] of [[-56,-10,1,164],[56,-10,1,164],[0,-92,112,1],[0,72,112,1]]){addBox(w,[x,3,z],[sx,6,sz],COLORS.darkMetal);addCollider(w,x,z,sx,sz,{minY:0,maxY:6,id:`${id}-outer`})}
  addBox(w,[0,.03,-10],[10,.06,154],cMix(COLORS.concrete,accent,.12));for(const z of[50,20,-10,-40,-70]){addBox(w,[-29,.04,z],[40,.08,24],cMix(COLORS.concrete,col,.2));addBox(w,[29,.04,z],[40,.08,24],cMix(COLORS.concrete,col,.2));for(const x of[-49,-9,9,49]){const wz=z+(x<0?-12:12);addBox(w,[x,2.5,wz],[.45,5,24],COLORS.darkMetal);addCollider(w,x,wz,.45,24,{minY:0,maxY:5,id:`${id}-divider-${x}-${z}`})}for(const x of[-29,29]){addBox(w,[x,5.65,z],[40,.18,24],COLORS.darkMetal);addBox(w,[x,2.9,z+(x<0?11.6:-11.6)],[40,.3,.3],accent,0,{emissive:.25})}}
  for(let z=56;z>-78;z-=14){addBox(w,[0,2.5,z],[.16,5,.16],COLORS.darkMetal);addBox(w,[0,4.8,z],[5.2,.14,.14],accent,0,{emissive:.18})}
  for(const z of[48,18,-12,-42])for(const x of[-29,29]){const theme=z>35?'bunk':z>5?'clinic':z>-25?'shelf':'workbench';for(let k=0;k<4;k++)addDetailPreset(w,theme,x+(k-1.5)*4.2,0,z+(k%2?3:-3),k%2?0:Math.PI,.88,detailRng(`${id}-${x}-${z}-${k}`))}
  const [cn,cr,ci]=d.caretaker;addHumanNPC(w,`${id}-caretaker`,cn,cr,[-18,0,49],col,{initials:ci,dialogue:`${id}-caretaker`,yaw:Math.PI/2});addInteract(w,`${id}-caretaker-talk`,[-18,1.1,49],`Parler à ${cn}`,()=>openDialogue(speaker(cn,cr,ci),d.experiment,[{text:'Consigner le témoignage.',onChoose:()=>{state.flags.notes[`testimony-${id}`]=true;closeDialogue()}},{text:'Prendre congé.',onChoose:closeDialogue}]),{radius:3.2});
  const types=d.enemies;const positions=[[-30,0,4],[30,0,-10],[-25,0,-39],[25,0,-55],[0,0,-64]];positions.forEach((p,i)=>{const type=i===4?d.boss[1]:types[i%types.length],name=i===4?d.boss[2]:enemyName(type);addEnemy(w,i===4?d.boss[0]:`${id}-hostile-${i}`,type,name,p,{health:i===4?260:enemyDefaults(type).health,speed:enemyDefaults(type).speed,damage:enemyDefaults(type).damage,range:enemyDefaults(type).range,detect:32,boss:i===4,armor:i===4?.32:enemyDefaults(type).armor,attackType:enemyDefaults(type).attackType,statusOnHit:enemyDefaults(type).statusOnHit,burst:enemyDefaults(type).burst||1,loot:i===4?{weaponParts:3,circuitry:2,caps:70}:{scrap:1,ammo:5}})});
  addInteract(w,`${id}-log-a`,[-29,1,18],'Lire le journal d’habitation',()=>openNote(`log-a-${id}`,`JOURNAL ${d.code} · HABITAT`,d.experiment),{radius:3,kind:'archive'});addInteract(w,`${id}-log-b`,[29,1,-12],'Consulter les relevés de maintenance',()=>openNote(`log-b-${id}`,`JOURNAL ${d.code} · MAINTENANCE`,'Les relevés montrent que les pannes n’étaient pas toujours accidentelles : plusieurs équipes ont saboté les protocoles pour protéger les habitants.'),{radius:3,kind:'archive'});addInteract(w,`${id}-core`,[0,1.2,-78],`Accéder au noyau ${d.code}`,()=>shelterCoreInteraction(id),{radius:4,marker:!state.flags.shelterResolved?.[id],kind:'core'});addBox(w,[0,1.6,-82],[8,3.2,2.5],COLORS.darkMetal);addBox(w,[0,1.9,-80.7],[4.5,1.5,.12],accent,0,{emissive:.48});addLoot(w,`${id}-reward`,[7,1,-77],d.reward,1,WEAPONS[d.reward].name);addInteract(w,`${id}-exit`,[0,1.2,66],`Quitter l’abri vers ${DETAIL_ZONE_LABELS[d.parent]||d.parent}`,()=>loadZone(d.parent),{radius:4,kind:'link'});return w
}
