  part(draws,'cube',[p[0],1.92+bob,p[2]],[.16,1.55,.16],COLORS.darkMetal,yaw);
  part(draws,'cube',[p[0]+Math.cos(yaw)*.85,1.7+bob,p[2]+Math.sin(yaw)*.85],[1.4,.16,.16],COLORS.rust,yaw);
