function cadastreArchiveInteraction(){if(state.quest.main===49)setMainStage(50);if(state.flags.cadastreRead){openNote('aubagne-cadastre','CADASTRE DES ÉVACUÉS',`Orientation : ${state.quest.cadastreOutcome||'indéterminée'}. Le registre conserve désormais les corrections et leurs auteurs.`);return}openDialogue(speaker('CADASTRE AUB-HAUT','REGISTRES D’ÉVACUATION','AH'),'Le système a supprimé les logements non conformes afin de simplifier les itinéraires de secours. Des habitants réels ont disparu des plans.',[
  {text:'Conserver chaque correction et rendre les anciennes versions publiques.',tag:conditionTag('I',6),condition:()=>state.character.special.I>=6||state.perks.archivist>=2,onChoose:()=>resolveCadastre('versions')},
  {text:'Réintégrer toute présence attestée par deux habitants.',tag:conditionTag('C',6),condition:()=>state.character.special.C>=6,onChoose:()=>resolveCadastre('testimony')},
  {text:'Créer un registre communal indépendant de CONCORDE.',onChoose:()=>resolveCadastre('communal')},
  {text:'Sceller les dossiers contestés jusqu’à la fin de la crise.',onChoose:()=>resolveCadastre('sealed')},{text:'Quitter.',onChoose:closeDialogue}])}
function resolveCadastre(outcome){state.flags.cadastreRead=true;state.quest.cadastreOutcome=outcome;state.settlements.aubagnehaute=Math.max(1,state.settlements.aubagnehaute);state.flags.notes['aubagne-cadastre']=true;if(outcome==='versions'){repChange('ligue',2);gainXP(90,'Versions conservées')}if(outcome==='testimony'){repChange('collines',2);changeLoyalty('mireille',3)}if(outcome==='communal'){repChange('ligue',3);repChange('continuite',-1)}if(outcome==='sealed'){repChange('continuite',2)}setMainStage(51);closeDialogue();refreshWorld();saveGame(false)}
function aubagneStationInteraction(){if(state.flags.aubagneStationResolved){openNote('aubagne-station-charter','CHARTE DE LA GARE D’AUBAGNE',`Priorité : ${state.quest.aubagneStationOutcome||'non définie'}.`);return}openDialogue(speaker('SONIA MARTEL','CHEFFE DE GARE','SM'),'Le plan d’évacuation exclut les hameaux absents du cadastre. Qui monte dans les premiers trains ?',[
  {text:'Priorité aux personnes vulnérables, sans condition de registre.',onChoose:()=>resolveAubagneStation('vulnerable')},
  {text:'Des quotas par commune avec places réservées.',tag:conditionTag('C',6),condition:()=>state.character.special.C>=6,onChoose:()=>resolveAubagneStation('quotas')},
  {text:'Priorité aux équipes de secours et aux travailleurs indispensables.',onChoose:()=>resolveAubagneStation('service')},
  {text:'Billets payants pour financer davantage de convois.',onChoose:()=>resolveAubagneStation('paid')},{text:'Reporter.',onChoose:closeDialogue}])}
function resolveAubagneStation(outcome){state.flags.aubagneStationResolved=true;state.quest.aubagneStationOutcome=outcome;state.settlements.aubagnegare=Math.max(1,state.settlements.aubagnegare);if(outcome==='vulnerable'){repChange('secours',3);repChange('ligue',2)}if(outcome==='quotas'){repChange('collines',3)}if(outcome==='service'){repChange('rails',3)}if(outcome==='paid'){state.player.caps+=95;repChange('marches',3)}gainXP(95,'Gare d’Aubagne');setMainStage(52);closeDialogue();refreshWorld();saveGame(false)}
function ceramicKilnInteraction(){if(state.flags.kilnRestored){openNote('ceramic-charter','CHARTE DES CÉRAMISTES',`Production : ${state.quest.ceramicOutcome||'non définie'}.`);return}openDialogue(speaker('MAÏA AUBERT','MAÎTRESSE CÉRAMISTE','MA'),'Les fours peuvent produire des filtres, des briques coupe-feu ou des pièces vendables. Ils ne peuvent pas tout faire avant le prochain mistral.',[
  {text:'Priorité aux filtres d’eau pour les quartiers.',onChoose:()=>resolveCeramics('filters')},
  {text:'Priorité aux briques et gels coupe-feu.',onChoose:()=>resolveCeramics('firebreak')},
  {text:'Partager les fours entre les coopératives.',tag:conditionTag('I',6),condition:()=>state.character.special.I>=6||state.perks.ceramist>=1,onChoose:()=>resolveCeramics('cooperative')},
  {text:'Produire pour le marché afin d’acheter le reste.',onChoose:()=>resolveCeramics('market')},{text:'Reporter.',onChoose:closeDialogue}])}
function resolveCeramics(outcome){state.flags.kilnRestored=true;state.quest.ceramicOutcome=outcome;state.settlements.ceramiques=Math.max(1,state.settlements.ceramiques);state.inventory.clay=(state.inventory.clay||0)+3;if(outcome==='filters'){state.inventory.ceramicFilter+=3;repChange('eaux',2)}if(outcome==='firebreak'){state.inventory.fireGel+=2;repChange('secours',3)}if(outcome==='cooperative'){repChange('artisans',4);changeLoyalty('mireille',2)}if(outcome==='market'){state.player.caps+=120;repChange('marches',3)}gainXP(105,'Fours restaurés');setMainStage(53);closeDialogue();refreshWorld();saveGame(false)}
function culvertInteraction(){if(state.flags.culvertCleared){openNote('culvert-report','RAPPORT DES GALERIES',`Drainage : ${state.quest.culvertOutcome||'stable'}.`);return}if(world.enemies.some(e=>e.alive)){toast('La pompe est inaccessible tant que le nid reste actif.','bad');return}openDialogue(speaker('POMPE HUVEAUNE-S2','DRAINAGE MUNICIPAL','S2'),'La pompe peut rejeter les eaux contaminées vers l’aval, les filtrer lentement ou isoler la galerie.',[
  {text:'Installer des filtres céramiques et traiter l’eau.',condition:()=>state.inventory.ceramicFilter>=1,lockText:'Un filtre céramique est requis.',onChoose:()=>{removeItem('ceramicFilter');resolveCulvert('filtered')}},
  {text:'Purger immédiatement vers l’aval.',onChoose:()=>resolveCulvert('purged')},
  {text:'Isoler le bassin jusqu’à une réparation complète.',onChoose:()=>resolveCulvert('sealed')},{text:'Reporter.',onChoose:closeDialogue}])}
function resolveCulvert(outcome){state.flags.culvertCleared=true;state.quest.culvertOutcome=outcome;state.settlements.huveaunesouterraine=Math.max(1,state.settlements.huveaunesouterraine);if(outcome==='filtered'){repChange('eaux',3);repChange('collines',2)}if(outcome==='purged'){repChange('eaux',1);repChange('rade',-1)}if(outcome==='sealed'){repChange('secours',2)}gainXP(120,'Sous l’Huveaune');setMainStage(54);closeDialogue();refreshWorld();saveGame(false)}
function mireilleTruthInteraction(){if(state.flags.mireilleTruthResolved){openNote('barral-truth','DOSSIER BARRAL',`Décision : ${state.quest.mireilleTruthOutcome||'non définie'}.`);return}openDialogue(speaker('Mireille Barral','TECHNICIENNE DE LA LIGUE','MB'),'Mon père a retiré des hameaux du plan officiel pour empêcher CONCORDE de les réquisitionner. Il les a sauvés à court terme, puis leurs habitants ont disparu des secours. Je dois dire la vérité, mais je refuse qu’on transforme son geste en simple crime.',[
  {text:'Publier le dossier complet, contexte et conséquences.',onChoose:()=>resolveMireilleTruth('truth')},
  {text:'Confier l’enquête à une commission des habitants concernés.',tag:conditionTag('C',7),condition:()=>state.character.special.C>=7,onChoose:()=>resolveMireilleTruth('commission')},
  {text:'Protéger Gabriel et corriger seulement les listes actuelles.',onChoose:()=>resolveMireilleTruth('protect')},
  {text:'Utiliser le dossier pour imposer la Ligue.',onChoose:()=>resolveMireilleTruth('leverage')},{text:'Laisser Mireille réfléchir.',onChoose:closeDialogue}])}
function resolveMireilleTruth(outcome){state.flags.mireilleTruthResolved=true;state.quest.mireilleTruthOutcome=outcome;if(outcome==='truth'){changeLoyalty('mireille',12);repChange('ligue',2)}if(outcome==='commission'){changeLoyalty('mireille',9);repChange('collines',3)}if(outcome==='protect'){changeLoyalty('mireille',2);repChange('continuite',-1)}if(outcome==='leverage'){changeLoyalty('mireille',-12);repChange('ligue',4)}gainXP(110,'Le nom de Barral');setMainStage(55);closeDialogue();saveGame(false)}
function rouxRescueInteraction(){if(state.flags.rouxRescueResolved){openNote('roux-rescue','RAPPORT DE RECHERCHE','Roux a retrouvé la balise et conduit les secours à travers les conduites.');return}if(!state.flags.rouxRecruited){toast('Roux doit être recruté pour suivre cette piste.','bad');return}openDialogue(speaker('ROUX','ÉCLAIREUR CANIN','RX'),'Roux gratte le sol puis disparaît dans une conduite latérale. Une balise de secours répond faiblement derrière la grille.',[
  {text:'Le suivre immédiatement.',onChoose:()=>resolveRouxRescue('follow')},
  {text:'Marquer la route et revenir avec une équipe.',onChoose:()=>resolveRouxRescue('team')},
  {text:'Récupérer seulement la balise.',onChoose:()=>resolveRouxRescue('beacon')},{text:'Attendre.',onChoose:closeDialogue}])}
function resolveRouxRescue(outcome){state.flags.rouxRescueResolved=true;state.quest.rouxRescueOutcome=outcome;if(outcome==='follow'){changeLoyalty('roux',15);repChange('secours',3);state.inventory.stimpak+=2}if(outcome==='team'){changeLoyalty('roux',9);repChange('ligue',2);state.inventory.scrap+=3}if(outcome==='beacon'){changeLoyalty('roux',-6);state.inventory.rescueBeacon+=1;state.player.caps+=45}gainXP(100,'Le chien des cendres');setMainStage(56);closeDialogue();saveGame(false)}
function firewatchInteraction(){if(state.quest.main===56)setMainStage(57);if(state.flags.firewatchActive){openNote('firewatch-charter','CHARTE DES VIGIES',`Réseau : ${state.quest.firewatchOutcome||'actif'}.`);return}openDialogue(speaker('RACHID ESCOFFIER','CHEF DES VIGIES','RE'),'Le front de feu approche. La vigie peut centraliser les ordres, distribuer les clés aux communes ou ouvrir toutes les fréquences.',[
  {text:'Réseau public de secours ouvert à tous.',onChoose:()=>resolveFirewatch('public')},
  {text:'Clés distribuées aux communes et aux ateliers.',onChoose:()=>resolveFirewatch('distributed')},
  {text:'Commandement central pour traverser la crise.',onChoose:()=>resolveFirewatch('command')},
  {text:'Abonnements privés pour financer les équipements.',onChoose:()=>resolveFirewatch('private')},{text:'Reporter.',onChoose:closeDialogue}])}
function resolveFirewatch(outcome){state.flags.firewatchActive=true;state.flags.fireFrontContained=true;state.flags.aubagneCouncilReady=true;state.quest.firewatchOutcome=outcome;state.settlements.garlabanpass=Math.max(1,state.settlements.garlabanpass);state.economy.contracts.firewatch=1;if(outcome==='public'){repChange('secours',4);repChange('ligue',2)}if(outcome==='distributed'){repChange('collines',3);repChange('artisans',2)}if(outcome==='command'){repChange('continuite',3);repChange('secours',1)}if(outcome==='private'){state.player.caps+=135;repChange('marches',3);repChange('secours',-1)}gainXP(140,'Ligne de feu contenue');setMainStage(58);closeDialogue();refreshWorld();toast('Conseil d’Aubagne disponible dans la Ville Haute.','good');saveGame(false)}
function aubagneCouncilInteraction(){if(state.quest.aubagneComplete){openNote('aubagne-charter','CHARTE D’AUBAGNE',`Orientation : ${state.quest.aubagneOutcome||'indéterminée'}.`);return}if(state.quest.main!==58&&state.mode!=='free'){toast('Les accords du cadastre, de la gare, des fours et des vigies ne sont pas réunis.','bad');return}openDialogue(speaker('CONSEIL D’AUBAGNE','COMMUNES, ARTISANS, CHEMINOTS & VIGIES','CA'),'Qui gouvernera les noms, les évacuations, les filtres et les secours dans le pays d’Aubagne ?',[
  {text:'Une fédération des communes avec droits communs.',onChoose:()=>completeAubagneChapter('federation')},
  {text:'Un service public territorial coordonné.',onChoose:()=>completeAubagneChapter('public')},
  {text:'Les coopératives d’ateliers et de quartiers.',tag:conditionTag('C',8),condition:()=>state.character.special.C>=8||state.rep.artisans+state.rep.collines>=8,onChoose:()=>completeAubagneChapter('cooperative')},
  {text:'Des concessions auditées finançant les secours.',onChoose:()=>completeAubagneChapter('concessions')},{text:'Reporter.',onChoose:closeDialogue}])}
function completeAubagneChapter(outcome){state.quest.aubagneOutcome=outcome;state.quest.aubagneComplete=true;state.quest.main=59;state.flags.notes['aubagne-charter']=true;state.settlements.aubagnehaute=Math.max(1,state.settlements.aubagnehaute);if(outcome==='federation'){repChange('ligue',4);repChange('collines',4);changeLoyalty('mireille',8)}if(outcome==='public'){repChange('secours',4);repChange('eaux',2);repChange('rails',2)}if(outcome==='cooperative'){repChange('artisans',5);repChange('ligue',2)}if(outcome==='concessions'){repChange('marches',4);state.player.caps+=175}gainXP(350,'Chapitre VI terminé');achievement('earth-and-fire','La Terre et le Feu');closeDialogue();saveGame(false);setTimeout(()=>showEnding('aubagne'),350)}

function boulesInteraction(){
  const stamp=Math.floor((state.playTime||0)/240)+(state.economy.travelCount||0);if(state.flags.worldChanges.boulesStamp===stamp){openDialogue(speaker('PAULE ARTAUD','ARBITRE DU BOULODROME','PA'),'Vous avez déjà joué cette tournée. Revenez après un voyage ou une nouvelle journée de terrain.',[{text:'Observer la partie.',onChoose:closeDialogue}]);return}
  openDialogue(speaker('PAULE ARTAUD','ARBITRE DU BOULODROME','PA'),'Ici, personne ne demande votre dossier. Seulement si vous pointez, tirez ou tentez de parler jusqu’à ce que la boule se rapproche toute seule.',[
    {text:'Pointer avec patience.',tag:conditionTag('P',5),condition:()=>state.character.special.P>=5,onChoose:()=>resolveBoules('point')},
    {text:'Tirer franchement.',tag:conditionTag('A',5),condition:()=>state.character.special.A>=5,onChoose:()=>resolveBoules('shoot')},
    {text:'Lire le terrain et les habitudes adverses.',tag:conditionTag('L',5),condition:()=>state.character.special.L>=5,onChoose:()=>resolveBoules('read')},
    {text:'Parier 12 capsules sur un lancer risqué.',condition:()=>state.player.caps>=12,onChoose:()=>{state.player.caps-=12;resolveBoules('bet')}},
    {text:'Quitter le terrain.',onChoose:closeDialogue}
  ])
}
function resolveBoules(style){const score=(style==='point'?state.character.special.P:style==='shoot'?state.character.special.A:style==='read'?state.character.special.L:(state.character.special.L+Math.random()*5))+(state.perks.urbanExplorer||0)*1.5+Math.random()*4;state.flags.worldChanges.boulesStamp=Math.floor((state.playTime||0)/240)+(state.economy.travelCount||0);state.flags.worldChanges.boulesGames=(state.flags.worldChanges.boulesGames||0)+1;if(score>=8){state.player.caps+=style==='bet'?38:18;gainXP(22,'Partie de Belsunce');repChange('rade',1);closeDialogue();toast('Victoire au boulodrome · la place vous reconnaît.','good')}else{gainXP(8,'Partie de Belsunce');closeDialogue();toast('Défaite honorable. Paule vous offre quand même un verre d’eau.');addItem('water',1)}saveGame(false)}
function talkMireya(){openDialogue(speaker('Mireya Vidal','PROJECTIONNISTE GOULE','MV'),state.flags.cinemaResolved?'Les bobines circulent selon votre charte. Une copie dans chaque quartier vaut mieux qu’un original enfermé.':'J’étais déjà officiellement morte quand j’ai filmé les marchés de Belsunce. Les images ont donc plus de droits que moi. Calibrez le projecteur et personne ne pourra prétendre que nous avons disparu.',[{text:'Examiner la salle de projection.',onChoose:()=>{closeDialogue();cinemaEntryInteraction()}},{text:'Demander pourquoi les bobines comptent.',onChoose:()=>openNote('mireya-testimony','TÉMOIGNAGE DE MIREYA','Les films portent des dates, des visages, des commerces et des soins postérieurs aux radiations administratives. Ils forment une preuve collective de présence.')},{text:'Prendre congé.',onChoose:closeDialogue}])}
function talkCelineRade(){openDialogue(speaker('Céline Fabre','DÉLÉGUÉE DE LA COMMUNE','CF'),state.quest.main===47?'Les quartiers sont prêts. Ce conseil décidera si Marseille appartient à ceux qui y vivent, à ceux qui l’entretiennent ou à ceux qui savent signer les contrats.':'La Canebière relie tout le monde sur les cartes. Dans la réalité, chaque étage possède son propre droit de passage.',[{text:'Convoquer le conseil.',condition:()=>state.quest.main===47,onChoose:()=>{closeDialogue();marseilleCouncilInteraction()}},{text:'Prendre congé.',onChoose:closeDialogue}])}
function talkCinemaStudent(){openDialogue(speaker('Ilyes Artaud','APPRENTI ARCHIVISTE','IA'),'Chaque réparation du projecteur modifie un peu la lumière. Mireya dit qu’une mauvaise restauration peut effacer un visage aussi sûrement qu’un registre.',[{text:'Recevoir une note de calibration.',onChoose:()=>{state.flags.notes['projection-hint']=true;toast('Indice : privilégier une mise au point haute, une synchronisation basse et une lumière médiane.','good');closeDialogue()}},{text:'Prendre congé.',onChoose:closeDialogue}])}
function talkStationMedic(){openDialogue(speaker('Amina Fabre','TRIEUSE DES VEILLEURS','AF'),'Les contrôles transforment les escaliers en salle d’attente. Certains patients meurent avec une autorisation en cours de validation.',[{text:'Enregistrer les transferts refusés.',onChoose:()=>{state.flags.notes['station-medical-refusals']=true;repChange('veilleurs',1);closeDialogue()}},{text:'Prendre congé.',onChoose:closeDialogue}])}
function talkStationGuard(){openDialogue(speaker('Dario Coste','GARDE DE LA RADE','DC'),'Le Guichetier connaît chaque règlement, sauf celui qui dit qu’une personne devant lui existe réellement.',[{text:'Demander l’accès aux galeries.',condition:()=>state.flags.stationResolved,onChoose:()=>{closeDialogue();loadZone('tunnels')}},{text:'Prendre congé.',onChoose:closeDialogue}])}

function talkSofiane(){
  openDialogue(speaker('Sofiane Martel','AIGUILLEUR DE LA VALLÉE','SM'),state.flags.trainRestored?'Le train roule. Maintenant, tout le monde prétend avoir toujours soutenu sa remise en route.':'La ligne n’est pas morte. Elle attend seulement que quelqu’un accepte la responsabilité de la réveiller.',[
    {text:'« Que bloque exactement le contrôleur ? »',onChoose:()=>openDialogue(speaker('Sofiane Martel','AIGUILLEUR DE LA VALLÉE','SM'),'Il considère les équipes de maintenance comme “personnel temporaire décédé”. Les rails sont praticables, mais le tunnel et ses scolopendres rendent toute réparation dangereuse.',[{text:'Examiner le poste de contrôle.',onChoose:closeDialogue}])},
    {text:'Recevoir une poignée de pièces.',condition:()=>!state.flags.looted['sofiane-parts'],onChoose:()=>{state.flags.looted['sofiane-parts']=true;addResource('scrap',2);closeDialogue()}},
    {text:'Prendre congé.',onChoose:closeDialogue}
  ])
}
function talkRailWorker(){openDialogue(speaker('Inès Vidal','MÉCANICIENNE DES RAILS','IV'),'Une ligne ouverte sans équipe protégée est seulement une autre façon de nous user plus vite. Notez-le avant de toucher au contrôleur.',[{text:'Enregistrer les garanties demandées.',onChoose:()=>{state.flags.notes['rail-guarantees']=true;repChange('rails',1);closeDialogue()}},{text:'Prendre congé.',onChoose:closeDialogue}])}
function talkAlix(){openDialogue(speaker('Alix Giraud','BOTANISTE DU JARDIN','AG'),state.flags.gardenResolved?'Le Jardin suit désormais la décision que vous avez imposée. Les plantes, elles, n’ont signé aucun accord.':'Le Jardin peut nourrir la vallée, restaurer des espèces ou devenir un coffre réservé à quelques-uns. Les mêmes semences servent aux trois projets.',[{text:'Examiner le programme du Jardin.',onChoose:()=>{closeDialogue();gardenInteraction()}},{text:'Demander des réactifs.',condition:()=>!state.flags.looted['alix-kit'],onChoose:()=>{state.flags.looted['alix-kit']=true;addResource('chemicals',1);addResource('food',1);closeDialogue()}},{text:'Prendre congé.',onChoose:closeDialogue}])}
function talkHillGuard(){openDialogue(speaker('Théo Marès','GARDE DES COLLINES','TM'),'Les sangliers ne sont pas mauvais. Ils sont gros, affamés et convaincus que tout leur appartient. Ça ressemble à beaucoup de conseils municipaux.',[{text:'Demander où trouver la grotte.',onChoose:()=>{state.flags.notes['garlaban-cave']=true;toast('Grotte du Garlaban ajoutée aux notes.','good');closeDialogue()}},{text:'Prendre congé.',onChoose:closeDialogue}])}
function talkTess(){openDialogue(speaker('Tess Delorme','DÉLÉGUÉE DE LA COOPÉRATIVE','TD'),state.flags.paludsResolved?'Les presses tournent selon l’accord conclu. Je vous préviendrai le jour où le papier commencera à produire des pièces.':'Les Paluds peuvent alimenter tout le réseau. La question est de savoir si le réseau nous appartient aussi.',[{text:'Ouvrir la négociation industrielle.',onChoose:()=>{closeDialogue();paludsInteraction()}},{text:'Demander un lot de composants.',condition:()=>!state.flags.looted['tess-parts'],onChoose:()=>{state.flags.looted['tess-parts']=true;addResource('scrap',2);closeDialogue()}},{text:'Prendre congé.',onChoose:closeDialogue}])}
function talkPaludsWorker(){openDialogue(speaker('Simon Causse','CONTREMAÎTRE INDÉPENDANT','SC'),'Un contrat exclusif remplit les carnets. Un contrat ouvert remplit les routes. Un contrat ouvrier remplit parfois les assemblées avant les entrepôts.',[{text:'Enregistrer les positions des équipes.',onChoose:()=>{state.flags.notes['paluds-workers']=true;repChange('arsenal',1);closeDialogue()}},{text:'Prendre congé.',onChoose:closeDialogue}])}
function talkAdrien(){openDialogue(speaker('Adrien Faure','INTENDANT DU BELVÉDÈRE','AF'),state.flags.belvedereResolved?'Les portes suivent votre règle. Je ne garantis pas que les habitants suivront votre conscience.':'Le Belvédère a de l’eau et des lits. Pas assez pour tous, disent mes comptes. Assez pour davantage, disent ceux qui attendent dehors.',[{text:'Décider de la politique des portes.',onChoose:()=>{closeDialogue();belvedereInteraction()}},{text:'Prendre congé.',onChoose:closeDialogue}])}
function talkLouna(){openDialogue(speaker('Louna Ben Amar','PORTE-PAROLE DES RÉFUGIÉS','LB'),'On nous demande des preuves de domicile pour entrer. Notre domicile est précisément l’endroit que nous avons dû quitter.',[{text:'Enregistrer la liste des familles.',onChoose:()=>{state.flags.notes['refugee-list']=true;repChange('veilleurs',1);closeDialogue()}},{text:'Donner deux vivres.',condition:()=>state.inventory.food>=2,onChoose:()=>{state.inventory.food-=2;repChange('veilleurs',1);gainXP(12,'Aide aux réfugiés');closeDialogue()}},{text:'Prendre congé.',onChoose:closeDialogue}])}
function talkMaelis(){openDialogue(speaker('Maëlys Roche','GARDE-CÔTE DES FRANCS','MR'),state.flags.beaconLit?'La balise porte plus loin que nos voix. Les pilotes sauront enfin quelles criques éviter.':'Le Roi de cale s’est installé sous la balise. On peut l’abattre, le détourner ou alimenter la tour par le bunker.',[{text:'Demander un bulletin côtier.',onChoose:()=>openNote('coastal-weather','BULLETIN DES FRANCS','Mistral irrégulier. Brumes sèches sur les hauteurs. Activité radioactive intermittente dans les criques profondes.')},{text:'Prendre congé.',onChoose:closeDialogue}])}

function trainControlInteraction(){
  if(state.flags.trainRestored){openNote('huveaune-line','LIGNE DE L’HUVEAUNE',`Service actif. Protocole : ${state.quest.trainOutcome}. Les convois relient désormais Aubagne aux Paluds et aux collines.`);return}
  if(state.quest.main<13){toast('Le contrôleur n’accepte pas encore votre mandat régional.');return}
  openDialogue(speaker('POSTE DE LA PENNE','CONTRÔLE FERROVIAIRE','LP'),'La voie est praticable. Le système refuse toutefois de reconnaître les équipes de maintenance et verrouille le tunnel nord.',[
    {text:'Réparer les capteurs et reconnaître les équipes.',tag:conditionTag('I',5),condition:()=>state.character.special.I>=5||state.inventory.circuitry>=1,lockText:'Intelligence 5 ou un circuit requis.',onChoose:()=>resolveTrain('repair')},
    {text:'Négocier un statut permanent pour les cheminots.',tag:conditionTag('C',5),condition:()=>state.character.special.C>=5||state.flags.notes['rail-guarantees'],lockText:'Charisme 5 ou garanties des équipes requises.',onChoose:()=>resolveTrain('workers')},
    {text:'Démonter les sécurités et faire circuler un convoi léger.',tag:conditionTag('S',5),condition:()=>state.character.special.S>=5,onChoose:()=>resolveTrain('bypass')},
    {text:'Reporter la remise en service.',onChoose:closeDialogue}
  ])
}
