function hideAllScreens(){document.querySelectorAll('.screen,.modal').forEach(e=>e.classList.remove('active'));document.querySelectorAll('.modal').forEach(e=>e.classList.add('hidden'));$('dialogue').classList.add('hidden');$('pipboy').classList.add('hidden');$('vats').classList.add('hidden')}
