let creatorSpecial={S:3,P:3,E:3,C:3,I:3,A:3,L:3};
function specialRemaining(){return 21-Object.values(creatorSpecial).reduce((a,b)=>a+b,0)}
function renderCreator(){
  $('specialRemaining').textContent=specialRemaining();const list=$('specialList');list.innerHTML='';Object.entries(creatorSpecial).forEach(([k,v],idx)=>{const row=document.createElement('div');row.className=`special-row ${idx===0?'selected':''}`;row.innerHTML=`<span class="letter">${k}</span><span class="attr"><b>${SPECIAL_INFO[k][0]}</b><small>${SPECIAL_INFO[k][1]}</small></span><span class="stepper"><button data-k="${k}" data-d="-1" aria-label="Retirer un point">−</button><output>${v}</output><button data-k="${k}" data-d="1" aria-label="Ajouter un point">+</button></span>`;row.onclick=()=>{document.querySelectorAll('.special-row').forEach(r=>r.classList.remove('selected'));row.classList.add('selected');$('specialHelp').textContent=SPECIAL_INFO[k][1]};list.appendChild(row)});list.querySelectorAll('button').forEach(b=>b.onclick=e=>{e.stopPropagation();const k=b.dataset.k,d=Number(b.dataset.d);if(d>0&&specialRemaining()<=0){audio.empty();return}creatorSpecial[k]=clamp(creatorSpecial[k]+d,1,10);audio.ui(420+creatorSpecial[k]*25,.035);renderCreator()})
}
