let debugRenderPaused=false;
function frame(ts){
  const dt=Math.min(.05,(ts-lastFrame)/1000||.016);lastFrame=ts;gameClock=ts/1000;if(mode==='PLAYING')updatePlayer(dt);if(mode==='MENU')menuOrbit+=dt*.065;if(!debugRenderPaused){sky?.draw(currentEnv(),ts);if(renderer&&world){const camera=getCamera(ts/1000),draws=collectDraws(ts/1000);renderer.render(draws,camera,currentEnv())}}updateHUD();requestAnimationFrame(frame)
}


