const V013_ZONE_TITLE=(id)=>DETAIL_ZONE_LABELS[id]||SHELTER_DEFS[id]? (SHELTER_DEFS[id]?`Abri ${SHELTER_DEFS[id].code} · ${SHELTER_DEFS[id].title}`:DETAIL_ZONE_LABELS[id]) : (SETTLEMENT_INFO[id]?.name||id.replace(/-/g,' '));
function v013LoreSeed(id){return detailHash(`V013-LORE-${id}`)}
function v013LoreContent(id){const title=V013_ZONE_TITLE(id),shelter=SHELTER_DEFS[id],n=v013LoreSeed(id),action=['power','cache','security','water','broadcast'][n%5];if(shelter)return{terminalTitle:`TERMINAL ${shelter.code} · NOYAU LOCAL`,entries:[['PROTOCOLE INITIAL',shelter.experiment],['JOURNAL DU PERSONNEL',`Le personnel de ${shelter.code} a commencé par corriger les chiffres. Puis il a protégé les habitants en corrigeant les règles. Les deux gestes ne sont pas toujours distinguables dans les archives.`],['DERNIÈRE SYNCHRONISATION',`Les capteurs signalent encore des voix, des pas et des équipements en service. Le système continue pourtant de classer plusieurs résidents comme ressources inactives.`]],action,noteTitle:`Note froissée · ${shelter.code}`,note:`Ne fais pas confiance au résumé du noyau. Regarde qui a signé, qui a été effacé et qui a continué à entretenir les portes. Les chiffres ne sont jamais seuls.`,tapeTitle:`Dernière bande de ${shelter.code}`,speaker:shelter.caretaker[0],lines:[`Test de bande. Ici ${shelter.caretaker[0]}.`,`Le protocole disait : ${shelter.experiment}`,`Nous avons essayé de préserver les personnes avant de préserver l’expérience.`,`Certains nous appelleront saboteurs. Qu’ils viennent d’abord lire les listes.`,`Si quelqu’un retrouve cette bande, qu’il laisse une copie à la surface.`]};const theme=ldThemesFor({id})[0]||'rural',story={urban:'les étages habités derrière les façades condamnées',market:'les vendeurs qui tiennent les comptes quand les terminaux mentent',rail:'les voyageurs disparus entre deux listes de départ',industrial:'les équipes qui continuent d’entretenir les machines sans contrat',maritime:'les équipages secourus sans avoir pu payer leur passage',rural:'les familles qui entretiennent les restanques et les sentiers',medical:'les patients traités après leur prétendu décès administratif',ceramic:'les fours et les filtres produits pour toute la région',fire:'les vigies qui refusent d’abandonner les hameaux',vault:'les habitants classés comme variables expérimentales',indoor:'les équipes de maintenance restées après l’évacuation'}[theme]||'les habitants restés sur place';return{terminalTitle:`TERMINAL LOCAL · ${title.toUpperCase()}`,entries:[['ÉTAT DU SECTEUR',`Le terminal recense ${story}. Plusieurs entrées ont été modifiées après la dernière synchronisation CONCORDE.`],['MAIN COURANTE',`Une équipe locale a conservé des copies papier, des témoins et des pièces détachées. Les divergences sont volontaires : elles empêchent un effacement automatique de devenir définitif.`],['ACTION EN ATTENTE',`Le réseau peut encore alimenter un service, ouvrir une réserve, neutraliser une sécurité, redistribuer de l’eau ou diffuser les archives. Toute action restera inscrite.`]],action,noteTitle:`Note de terrain · ${title}`,note:`On reconnaît un lieu vivant à ce qu’il répare. Ici, quelqu’un a remplacé les câbles, partagé les outils et laissé le passage libre. Le rapport officiel ne mentionne rien de cela.`,tapeTitle:`Voix de ${title}`,speaker:['Une habitante','Un ouvrier','Une vigie','Un voyageur','Une soignante'][n%5],lines:[`Bande locale, ${title}.`,`Le terminal dit que le secteur fonctionne normalement.`,`Il ne voit pas les portes calées avec des briques, ni les repas divisés en portions plus petites.`,`Nous avons gardé les noms et les itinéraires sur papier.`,`Faites une copie avant de repartir.`]}}
const V013_LORE_CATALOG=Object.fromEntries(ALL_ZONE_IDS.map(id=>[id,v013LoreContent(id)]));

