const v012BaseStateForV013=baseState;baseState=function(){const s=v013EnsureLoreState(v012BaseStateForV013());for(const id of V013_SHELTER_IDS)s.settlements[id]??=0;for(const id of V013_AMMO_IDS)s.ammo[id]??=0;return s};
const v012MigrateForV013=migrateState;migrateState=function(old){const m=v013EnsureLoreState(v012MigrateForV013(old||{})),ol=old?.lore||{};for(const k of['terminals','terminalActions','notes','holotapes','holotapePlays','localQuests','localQuestOutcomes'])m.lore[k]={...(m.lore[k]||{}),...(ol[k]||{})};for(const id of V013_SHELTER_IDS)m.settlements[id]??=0;for(const id of V013_AMMO_IDS)m.ammo[id]??=0;m.version=VERSION;return m};

const V013_LOCAL_QUEST_ZONES=V013_SURFACE_IDS;
const V013_QUEST_TITLES=['Les pièces qui manquent','Un nom sur la route','La réserve commune','Les témoins du passage','Le câble et la parole','Ce que le registre oublie','Une porte pour deux quartiers','La liste de ceux qui restent'];
const V013_LOCAL_QUESTS=Object.fromEntries(V013_LOCAL_QUEST_ZONES.map((zone,i)=>[zone,{id:`local-${zone}`,zone,title:V013_QUEST_TITLES[i%V013_QUEST_TITLES.length],giver:V013_GIVER_NAMES[i%V013_GIVER_NAMES.length],witness:V013_WITNESS_NAMES[i%V013_WITNESS_NAMES.length],role:['habitante référente','responsable d’atelier','médiateur local','vigie de quartier','soignante bénévole'][i%5],faction:['ligue','rade','rails','collines','secours'][i%5],objective:`Récupérer la preuve matérielle conservée dans ${V013_ZONE_TITLE(zone)}.`,intro:`Une pièce manque dans notre dossier. Pas une abstraction : une preuve que des gens vivent, travaillent et réparent encore ici. Le terminal central ne la reconnaît plus.`,witnessLine:`J’ai vu où la preuve a été cachée. Suivez les passages secondaires et cherchez la balise jaune près de la dernière sous-zone.`,returnLine:`Vous l’avez trouvée. Maintenant il faut décider si elle sert d’abord aux habitants, au réseau ou à ceux qui prennent le risque de la transporter.`}]));

function v013FindPlacement(w,anchor,seed=0,radius=5){const rng=detailRng(`V013-POS-${w.id}-${seed}`);for(let r=radius;r<30;r+=2.8)for(let j=0;j<8;j++){const a=(j/8)*TAU+rng()*.2,x=anchor[0]+Math.cos(a)*r,z=anchor[2]+Math.sin(a)*r,y=w.id==='mer'?0:detailGround(w,x,z);if(w.id==='mer'||!ldInsideCollider(w,x,z,y,.8))return[x,y,z]}return ldFindFree(w,anchor[0],anchor[2])}
function v013AddTerminalModel(w,p){addBox(w,[p[0],p[1]+.55,p[2]],[2.6,1.1,1.1],COLORS.darkMetal);addBox(w,[p[0],p[1]+1.48,p[2]-.2],[2.2,1.15,.25],[.15,.25,.18]);addBox(w,[p[0],p[1]+1.5,p[2]-.34],[1.75,.78,.05],[.35,.85,.43],0,{emissive:.48});addBox(w,[p[0],p[1]+.15,p[2]+.45],[2.9,.3,1.7],COLORS.metal)}
function v013AddNoteModel(w,p){addCrate(w,p[0],p[2],COLORS.ochre2);addBox(w,[p[0],p[1]+1.02,p[2]],[.78,.035,.55],COLORS.white,.18)}
function v013AddHolotapeModel(w,p){addBox(w,[p[0],p[1]+.42,p[2]],[1.05,.62,.28],COLORS.darkMetal);for(const x of[-.25,.25])addPart(w,'cylinder',[p[0]+x,p[1]+.45,p[2]-.16],[.14,.08,.14],COLORS.ochre2,Math.PI/2);addBox(w,[p[0],p[1]+.68,p[2]],[.68,.18,.05],[.76,.66,.32],0,{emissive:.16})}
function v013PlaceLoreLayer(w){const subs=w.subzones||[],base=w.spawn||[0,0,0],terminalPos=v013FindPlacement(w,subs[2]?.pos||base,1,4),notePos=v013FindPlacement(w,subs[4]?.pos||base,2,4),tapePos=v013FindPlacement(w,subs[6]?.pos||base,3,4);v013AddTerminalModel(w,terminalPos);v013AddNoteModel(w,notePos);v013AddHolotapeModel(w,tapePos);addInteract(w,`v013-terminal-${w.id}`,[terminalPos[0],terminalPos[1]+1.1,terminalPos[2]],'Utiliser le terminal local',()=>openLoreTerminal(w.id),{radius:3.5,kind:'terminal',priority:.35});addInteract(w,`v013-note-${w.id}`,[notePos[0],notePos[1]+1,notePos[2]],'Lire la note de terrain',()=>collectFieldNote(w.id),{radius:3,kind:'note'});addInteract(w,`v013-tape-${w.id}`,[tapePos[0],tapePos[1]+.6,tapePos[2]],'Écouter l’holodisque',()=>collectHolotape(w.id),{radius:3,kind:'holotape'});let npcs=0,quest=0;if(V013_LOCAL_QUESTS[w.id]){const q=V013_LOCAL_QUESTS[w.id],giverPos=v013FindPlacement(w,subs[1]?.pos||base,4,3.5),witnessPos=v013FindPlacement(w,subs[3]?.pos||base,5,3.5),objectivePos=v013FindPlacement(w,subs[9]?.pos||subs[7]?.pos||base,6,4);addHumanNPC(w,`v013-giver-${w.id}`,q.giver,q.role,[giverPos[0],giverPos[1],giverPos[2]],COLORS.clothBlue,{initials:q.giver.split(/\s+/).map(x=>x[0]).join('').slice(0,2),dialogue:`v013-giver-${w.id}`,route:[[giverPos[0],giverPos[1],giverPos[2]],[giverPos[0]+3,giverPos[1],giverPos[2]+2],[giverPos[0]-2,giverPos[1],giverPos[2]+3]]});addHumanNPC(w,`v013-witness-${w.id}`,q.witness,'témoin local',[witnessPos[0],witnessPos[1],witnessPos[2]],COLORS.clothTan,{initials:q.witness.split(/\s+/).map(x=>x[0]).join('').slice(0,2),dialogue:`v013-witness-${w.id}`});addBox(w,[objectivePos[0],objectivePos[1]+.55,objectivePos[2]],[1.15,1.1,.8],COLORS.ochre);addBox(w,[objectivePos[0],objectivePos[1]+1.18,objectivePos[2]],[.72,.16,.55],COLORS.amber,0,{emissive:.28});addInteract(w,`v013-objective-${w.id}`,[objectivePos[0],objectivePos[1]+.8,objectivePos[2]],`Examiner la preuve locale`,()=>v013QuestObjective(w.id),{radius:3.2,kind:'quest',marker:(state.lore.localQuests[w.id]||0)===1});npcs=2;quest=1}w.loreStats={terminals:1,notes:1,holotapes:1,npcs,quests:quest};return w}
const v012BuildWorldForV013=buildWorld;buildWorld=function(id){let w=v012BuildWorldForV013(id);return v013PlaceLoreLayer(w)};

let terminalLoreState=null,holotapeState=null,holotapeTimer=null;
function openLoreTerminal(zoneId,fromArchive=false){const data=V013_LORE_CATALOG[zoneId];if(!data)return;state.lore.terminals[zoneId]=true;terminalLoreState={zoneId,index:0,fromArchive};previousMode=mode;mode='TERMINAL';document.exitPointerLock?.();$('terminalLoreScreen').classList.remove('hidden');renderLoreTerminal();saveGame(false)}
function renderLoreTerminal(){if(!terminalLoreState)return;const data=V013_LORE_CATALOG[terminalLoreState.zoneId],done=!!state.lore.terminalActions[terminalLoreState.zoneId];$('terminalLoreTitle').textContent=data.terminalTitle;$('terminalLoreEntries').innerHTML=data.entries.map((e,i)=>`<button data-terminal-entry="${i}" class="${i===terminalLoreState.index?'active':''}">${String(i+1).padStart(2,'0')} · ${escapeHtml(e[0])}</button>`).join('');$('terminalLoreEntryTitle').textContent=data.entries[terminalLoreState.index][0];$('terminalLoreText').textContent=data.entries[terminalLoreState.index][1];$('terminalLoreAction').textContent=done?'ACTION DÉJÀ EXÉCUTÉE':({power:'RÉTABLIR LE SERVICE LOCAL',cache:'OUVRIR LA RÉSERVE DE SECOURS',security:'DÉSACTIVER LA SÉCURITÉ HOSTILE',water:'RÉAFFECTER LES RÉSERVES D’EAU',broadcast:'DIFFUSER LES ARCHIVES'})[data.action];$('terminalLoreAction').disabled=done;$('terminalLoreEntries').querySelectorAll('[data-terminal-entry]').forEach(b=>b.onclick=()=>{terminalLoreState.index=Number(b.dataset.terminalEntry);audio.terminal();renderLoreTerminal()});$('terminalLoreAction').onclick=()=>executeTerminalAction(terminalLoreState.zoneId);$('terminalLoreExit').onclick=closeLoreTerminal}
function executeTerminalAction(zoneId){if(state.lore.terminalActions[zoneId])return;const data=V013_LORE_CATALOG[zoneId];state.lore.terminalActions[zoneId]=data.action;if(data.action==='power'){state.settlements[zoneId]=Math.max(1,state.settlements[zoneId]||0);addItem('circuitry',2)}else if(data.action==='cache'){addItem('scrap',5);addItem('stimpak',2);state.player.caps+=35}else if(data.action==='security'){for(const e of(world?.enemies||[]).filter(e=>['robot','protectron','turret','heavyTurret','notaryDrone','archiveDrone'].includes(e.type)).slice(0,3)){e.alive=false;state.flags.enemyDead[e.id]=true}toast('Protocoles de sécurité neutralisés.','good')}else if(data.action==='water'){addItem('water',4);repChange('eaux',1)}else{repChange('rade',1);state.flags.notes[`broadcast-${zoneId}`]=true;toast('Archive diffusée sur Radio Mistral.','good')}gainXP(28,'Action de terminal');achievement(`terminal-action-${Object.keys(state.lore.terminalActions).length}`,`${Object.keys(state.lore.terminalActions).length} terminaux reconfigurés`);saveGame(false);refreshWorld();renderLoreTerminal()}
function closeLoreTerminal(){$('terminalLoreScreen').classList.add('hidden');terminalLoreState=null;mode=previousMode==='PIP'?'PIP':'PLAYING';if(mode==='PLAYING')setTimeout(()=>$('gameCanvas').requestPointerLock?.(),80)}
function collectFieldNote(zoneId){const data=V013_LORE_CATALOG[zoneId];state.lore.notes[zoneId]=true;state.flags.notes[`field-${zoneId}`]=true;openNote(`field-${zoneId}`,data.noteTitle,data.note);const n=Object.keys(state.lore.notes).length;if([10,30,60,81].includes(n))achievement(`field-notes-${n}`,`${n} notes de terrain`);saveGame(false)}
function collectHolotape(zoneId){state.lore.holotapes[zoneId]=true;openHolotape(zoneId);const n=Object.keys(state.lore.holotapes).length;if([10,30,60,81].includes(n))achievement(`holotapes-${n}`,`${n} holodisques restaurés`);saveGame(false)}
function openHolotape(zoneId){const data=V013_LORE_CATALOG[zoneId];if(!data)return;state.lore.holotapes[zoneId]=true;state.lore.holotapePlays[zoneId]=(state.lore.holotapePlays[zoneId]||0)+1;holotapeState={zoneId,index:0,playing:false};previousMode=mode;mode='HOLOTAPE';document.exitPointerLock?.();$('holotapeScreen').classList.remove('hidden');renderHolotape();v013HolotapePlay(true)}
function renderHolotape(){if(!holotapeState)return;const data=V013_LORE_CATALOG[holotapeState.zoneId],total=data.lines.length;$('holotapeTitle').textContent=data.tapeTitle;$('holotapeSpeaker').textContent=data.speaker.toUpperCase();$('holotapeCounter').textContent=`${String(holotapeState.index+1).padStart(2,'0')} / ${String(total).padStart(2,'0')}`;$('holotapeText').textContent=data.lines[holotapeState.index];$('holotapeProgress').style.width=`${(holotapeState.index+1)/total*100}%`;$('holotapePlay').textContent=holotapeState.playing?'PAUSE':'LECTURE';$('holotapePrev').disabled=holotapeState.index===0;$('holotapeNext').disabled=holotapeState.index>=total-1;$('holotapePrev').onclick=()=>v013HolotapeStep(-1);$('holotapeNext').onclick=()=>v013HolotapeStep(1);$('holotapePlay').onclick=()=>v013HolotapePlay(!holotapeState.playing);$('holotapeExit').onclick=closeHolotape;if(settings.subtitles)subtitle(data.speaker,data.lines[holotapeState.index],3400)}
function v013HolotapeStep(d){if(!holotapeState)return;const total=V013_LORE_CATALOG[holotapeState.zoneId].lines.length;holotapeState.index=clamp(holotapeState.index+d,0,total-1);audio.terminal();renderHolotape()}
function v013HolotapePlay(on){if(!holotapeState)return;holotapeState.playing=on;clearInterval(holotapeTimer);if(on)holotapeTimer=setInterval(()=>{if(!holotapeState)return;const total=V013_LORE_CATALOG[holotapeState.zoneId].lines.length;if(holotapeState.index>=total-1){v013HolotapePlay(false);return}holotapeState.index++;audio.tone(240,.06,'square',.012,20);renderHolotape()},3600);renderHolotape()}
function closeHolotape(){clearInterval(holotapeTimer);holotapeTimer=null;$('holotapeScreen').classList.add('hidden');holotapeState=null;mode=previousMode==='PIP'?'PIP':'PLAYING';if(mode==='PLAYING')setTimeout(()=>$('gameCanvas').requestPointerLock?.(),80)}

function v013QuestObjective(zoneId){const stage=state.lore.localQuests[zoneId]||0,q=V013_LOCAL_QUESTS[zoneId];if(!q)return;if(stage===0){toast('Parlez d’abord à la personne référente.');return}if(stage===1){state.lore.localQuests[zoneId]=2;gainXP(24,'Preuve locale retrouvée');toast(`Retournez voir ${q.giver}.`,'good');saveGame(false);refreshWorld();return}toast(stage>=3?'Cette preuve a déjà trouvé sa place.':'La preuve est prête à être remise.')}
function v013ResolveLocalQuest(zoneId,outcome){const q=V013_LOCAL_QUESTS[zoneId];state.lore.localQuests[zoneId]=3;state.lore.localQuestOutcomes[zoneId]=outcome;if(outcome==='community'){repChange(q.faction,2);addItem('scrap',4);gainXP(65,'Service rendu au quartier')}else if(outcome==='payment'){state.player.caps+=110;addItem('weaponParts',2);gainXP(48,'Contrat local')}else{state.lore.terminals[zoneId]=true;state.lore.notes[zoneId]=true;repChange('continuite',1);gainXP(72,'Archive opposable')}const done=Object.values(state.lore.localQuests).filter(v=>v===3).length;if([5,15,30,V013_LOCAL_QUEST_ZONES.length].includes(done))achievement(`local-quests-${done}`,`${done} quêtes locales résolues`);closeDialogue();saveGame(false);refreshWorld()}
const v012TalkToNPCForV013=talkToNPC;talkToNPC=function(id){if(id.startsWith('v013-giver-')){const zone=id.slice('v013-giver-'.length),q=V013_LOCAL_QUESTS[zone],stage=state.lore.localQuests[zone]||0;if(stage===0)openDialogue(speaker(q.giver,q.role,q.giver.split(/\s+/).map(x=>x[0]).join('').slice(0,2)),q.intro,[{text:'Je vais retrouver cette preuve.',onChoose:()=>{state.lore.localQuests[zone]=1;closeDialogue();toast(`Quête locale : ${q.title}`,'good');saveGame(false);refreshWorld()}},{text:'Pas maintenant.',onChoose:closeDialogue}]);else if(stage===1)openDialogue(speaker(q.giver,q.role,'QL'),`La preuve est encore dans la boucle secondaire du secteur. ${q.objective}`,[{text:'Je continue les recherches.',onChoose:closeDialogue}]);else if(stage===2)openDialogue(speaker(q.giver,q.role,'QL'),q.returnLine,[{text:'La remettre à la communauté.',onChoose:()=>v013ResolveLocalQuest(zone,'community')},{text:'Demander une rémunération.',onChoose:()=>v013ResolveLocalQuest(zone,'payment')},{text:'En faire une archive publique.',onChoose:()=>v013ResolveLocalQuest(zone,'archive')}]);else openDialogue(speaker(q.giver,q.role,'QL'),`La preuve est enregistrée. Décision : ${state.lore.localQuestOutcomes[zone]||'communautaire'}. Le secteur s’en souviendra.`,[{text:'Terminer.',onChoose:closeDialogue}]);return}if(id.startsWith('v013-witness-')){const zone=id.slice('v013-witness-'.length),q=V013_LOCAL_QUESTS[zone];openDialogue(speaker(q.witness,'TÉMOIN LOCAL','TL'),q.witnessLine,[{text:'Merci pour le détail.',onChoose:closeDialogue}]);return}return v012TalkToNPCForV013(id)};

const v012RenderPipDataForV013=renderPipData;renderPipData=function(c){v012RenderPipDataForV013(c);const list=c.querySelector('.pip-list'),detail=c.querySelector('#dataDetail');if(!list||!detail)return;const counts={quests:Object.values(state.lore.localQuests).filter(v=>v===3).length,terminals:Object.keys(state.lore.terminals).length,actions:Object.keys(state.lore.terminalActions).length,notes:Object.keys(state.lore.notes).length,tapes:Object.keys(state.lore.holotapes).length};const defs=[['localquests',`QUÊTES LOCALES (${counts.quests}/${V013_LOCAL_QUEST_ZONES.length})`],['terminals',`TERMINAUX (${counts.terminals}/${ALL_ZONE_IDS.length})`],['fieldnotes',`NOTES TERRAIN (${counts.notes}/${ALL_ZONE_IDS.length})`],['holotapes',`HOLODISQUES (${counts.tapes}/${ALL_ZONE_IDS.length})`]];for(const [id,label] of defs){const b=document.createElement('button');b.dataset.v13data=id;b.textContent=label;list.insertBefore(b,list.querySelector('[data-data="achievements"]'));b.onclick=()=>{list.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(id==='localquests'){detail.innerHTML=`<h3>QUÊTES LOCALES · ${counts.quests}/${V013_LOCAL_QUEST_ZONES.length}</h3><p>Chaque secteur habité possède une personne référente, un témoin, une preuve physique et trois conclusions possibles.</p><div class="archive-grid">${V013_LOCAL_QUEST_ZONES.map(z=>{const q=V013_LOCAL_QUESTS[z],s=state.lore.localQuests[z]||0;return `<article class="archive-card ${s===3?'done':s?'seen':'locked'}"><div><b>${escapeHtml(q.title)}</b><small>${escapeHtml(V013_ZONE_TITLE(z))}</small></div><p>${s===0?'Non commencée':s===1?q.objective:s===2?'Preuve retrouvée : retournez voir la personne référente.':`Résolue · ${state.lore.localQuestOutcomes[z]}`}</p></article>`}).join('')}</div>`}else if(id==='terminals'){detail.innerHTML=`<h3>TERMINAUX · ${counts.terminals}/${ALL_ZONE_IDS.length}</h3><p>${counts.actions} action(s) persistante(s) exécutée(s).</p><div class="archive-grid">${ALL_ZONE_IDS.map(z=>{const d=V013_LORE_CATALOG[z],seen=state.lore.terminals[z],done=state.lore.terminalActions[z];return `<article class="archive-card ${done?'done':seen?'seen':'locked'}"><div><b>${escapeHtml(d.terminalTitle)}</b><small>${done?String(done).toUpperCase():seen?'CONSULTÉ':'NON DÉCOUVERT'}</small></div><p>${seen?escapeHtml(d.entries[0][1]):'Localisation encore inconnue.'}</p>${seen?`<button data-open-terminal="${z}">OUVRIR L’ARCHIVE</button>`:''}</article>`}).join('')}</div>`;detail.querySelectorAll('[data-open-terminal]').forEach(x=>x.onclick=()=>{closePipboy();openLoreTerminal(x.dataset.openTerminal,true)})}else if(id==='fieldnotes'){detail.innerHTML=`<h3>NOTES DE TERRAIN · ${counts.notes}/${ALL_ZONE_IDS.length}</h3><div class="archive-grid">${ALL_ZONE_IDS.map(z=>{const d=V013_LORE_CATALOG[z],seen=state.lore.notes[z];return `<article class="archive-card ${seen?'done':'locked'}"><div><b>${seen?escapeHtml(d.noteTitle):'NOTE NON IDENTIFIÉE'}</b><small>${seen?escapeHtml(V013_ZONE_TITLE(z)):'—'}</small></div><p>${seen?escapeHtml(d.note):'Cherchez les feuilles, registres et messages laissés dans les sous-zones.'}</p></article>`}).join('')}</div>`}else{detail.innerHTML=`<h3>HOLODISQUES · ${counts.tapes}/${ALL_ZONE_IDS.length}</h3><p>Lecture provisoire sous forme de bande sous-titrée. Les emplacements audio sont prêts pour de futures voix.</p><div class="archive-grid">${ALL_ZONE_IDS.map(z=>{const d=V013_LORE_CATALOG[z],seen=state.lore.holotapes[z];return `<article class="archive-card ${seen?'done':'locked'}"><div><b>${seen?escapeHtml(d.tapeTitle):'BANDE NON RESTAURÉE'}</b><small>${seen?escapeHtml(d.speaker):'—'}</small></div><p>${seen?escapeHtml(d.lines[0]):'Localisez la cassette dans le secteur.'}</p>${seen?`<button data-play-tape="${z}">LECTURE</button>`:''}</article>`}).join('')}</div>`;detail.querySelectorAll('[data-play-tape]').forEach(x=>x.onclick=()=>{closePipboy();openHolotape(x.dataset.playTape)})}}}};

const v012HandleKeyDownForV013=handleKeyDown;handleKeyDown=function(e){if(mode==='TERMINAL'){if(e.code==='Escape'||e.code==='KeyE')closeLoreTerminal();return}if(mode==='HOLOTAPE'){if(e.code==='Escape')closeHolotape();else if(e.code==='Space')v013HolotapePlay(!holotapeState?.playing);else if(e.code==='ArrowLeft')v013HolotapeStep(-1);else if(e.code==='ArrowRight')v013HolotapeStep(1);return}return v012HandleKeyDownForV013(e)};

v012MapNodes=function(){const nodes={...V012_MAP_SURFACE},grouped={};for(const [id,d] of Object.entries(SHELTER_DEFS)){const p=nodes[d.parent]||[900,400,'?'],n=grouped[d.parent]||0;grouped[d.parent]=n+1;const ring=Math.floor(n/8),slot=n%8,r=32+ring*18,a=-Math.PI/2+slot/8*TAU;nodes[id]=[p[0]+Math.cos(a)*r,p[1]+Math.sin(a)*r,d.code]}return nodes};
renderPipMap=function(c){const nodes=v012MapNodes(),routes=LD_ROUTES;const routeSvg=routes.map(([a,b])=>nodes[a]&&nodes[b]?`<path d="M${nodes[a][0]} ${nodes[a][1]} L${nodes[b][0]} ${nodes[b][1]}"/>`:'').join(''),nodeSvg=Object.entries(nodes).map(([id,[x,y,label]])=>{const edge=x>=1710,tx=edge?x-12:x+12,shelter=!!SHELTER_DEFS[id];return `<g data-map="${id}" class="map-node ${shelter?'shelter':''} ${!isZoneUnlocked(id)?'locked':''} ${world?.id===id?'current':''}"><circle cx="${x}" cy="${y}" r="${shelter?7:id==='vault'?8:10}"/><text x="${tx}" y="${y+4}" text-anchor="${edge?'end':'start'}">${label}</text></g>`}).join('');c.innerHTML=`<div class="pip-map"><svg viewBox="0 0 1900 860" role="img" aria-label="Carte schématique des ${ALL_ZONE_IDS.length} secteurs du réseau Mistral"><g class="map-routes">${routeSvg}</g>${nodeSvg}<path d="M0 790 Q320 720 650 785 T1900 740 V860 H0Z" fill="#1b4c46" opacity=".32"/><text x="22" y="838" fill="#629d86" font-family="monospace">MÉDITERRANÉE · ${ALL_ZONE_IDS.length} SECTEURS · ${SHELTER_IDS.length} ABRIS · TERMINAUX ${Object.keys(state.lore.terminals).length}/${ALL_ZONE_IDS.length}</text></svg><p>Onze sous-zones, six micro-intérieurs et des boucles secondaires structurent chaque secteur. Les nœuds ambrés sont les ${SHELTER_IDS.length} abris régionaux, en complément d’A-03.</p></div>`;c.querySelectorAll('[data-map]').forEach(n=>n.addEventListener('click',()=>{const id=n.dataset.map;if(!isZoneUnlocked(id)){toast('Destination non débloquée.','bad');return}if(id===world?.id)return;if(inCombat){toast('Impossible de voyager pendant un combat.','bad');return}if(id==='mer'&&!['mugel','ileverte'].includes(world?.id)){toast('Le skiff doit être mis à l’eau depuis un quai.','bad');return}closePipboy();loadZone(id)}))};

