function v014TalkCeline(){const q=state.foundation.q09;if(q.stage===0){openDialogue(speaker('Céline Fabre','CHIMISTE DES FILTRES','CF'),'Les cuves pourraient nettoyer le canal de Saint-Marcel. Il manque un catalyseur, un filtre alcalin et le registre qui prouve que l’usine devait aussi servir les quartiers voisins.',[{text:'Je vais réunir les trois éléments.',onChoose:()=>{q.stage=1;state.side.grandPropre=1;closeDialogue();refreshWorld();saveGame(false)}},{text:'Pas maintenant.',onChoose:closeDialogue}]);return}if(q.stage===1){const n=Object.values(q.parts).filter(Boolean).length;openDialogue(speaker('Céline Fabre','CHIMISTE DES FILTRES','CF'),`Vous avez retrouvé ${n}/3 élément(s). Les passages de maintenance relient les cuves, l’entrepôt et les toits.`,[{text:'Je poursuis.',onChoose:closeDialogue}]);return}if(q.stage===2){openDialogue(speaker('Céline Fabre','CHIMISTE DES FILTRES','CF'),'Tout est là. La question n’est plus technique : qui contrôlera la dépollution et les savons médicaux ?', [{text:'Un service public de nettoyage.',onChoose:()=>v014ResolveGrandPropre('public')},{text:'Une coopérative des ouvriers et habitants.',onChoose:()=>v014ResolveGrandPropre('cooperative')},{text:'Un contrat industriel audité.',onChoose:()=>v014ResolveGrandPropre('contract')},{text:'Récupérer l’équipement pour le terrain.',onChoose:()=>v014ResolveGrandPropre('salvage')}]);return}openDialogue(speaker('Céline Fabre','CHIMISTE DES FILTRES','CF'),`La savonnerie fonctionne selon la décision « ${q.outcome} ». Le canal et les ateliers en portent déjà les traces.`,[{text:'Terminer.',onChoose:closeDialogue}])}

function v014TalkLucien(){const q=state.companionQuests.lucien;if(q.stage===0){openDialogue(speaker('Lucien Artaud','ANCIEN ARCHIVISTE','LA'),'J’ai corrigé des dossiers pour sauver des familles, puis la Direction a utilisé mes corrections pour cacher ses propres exclusions. Mes signatures sont encore dans M-17, Le Guichet.',[{text:'Je retrouverai les corrections originales.',onChoose:()=>{q.stage=1;closeDialogue();saveGame(false)}},{text:'Vous devrez témoigner vous-même.',tag:conditionTag('C',6),condition:()=>state.character.special.C>=6,onChoose:()=>{q.stage=1;state.companions.loyalty.lucien+=5;closeDialogue();saveGame(false)}},{text:'Pas maintenant.',onChoose:closeDialogue}]);return}if(q.stage===1)openDialogue(speaker('Lucien Artaud','ANCIEN ARCHIVISTE','LA'),'Les preuves sont dans la réserve de révision de M-17. Elles portent ma signature et celle de la Direction.',[{text:'Je vais les chercher.',onChoose:closeDialogue}]);else if(q.stage===2)openDialogue(speaker('Lucien Artaud','ANCIEN ARCHIVISTE','LA'),'Vous avez les corrections. Que faisons-nous de ce dossier ?', [{text:'Publier le dossier avec votre témoignage.',onChoose:()=>v014RecruitLucien('testify')},{text:'Protéger les noms vulnérables, publier le mécanisme.',onChoose:()=>v014RecruitLucien('redact')},{text:'Le remettre à la Direction contre un mandat de réforme.',onChoose:()=>v014RecruitLucien('continuity')}]);else openDialogue(speaker('Lucien Artaud','COMPAGNON RECRUTÉ','LA'),'Je connais les raccourcis administratifs. Cette fois, ils serviront à ouvrir des portes.',[{text:state.player.activeCompanion==='lucien'?'Restez ici.':'Venez avec moi.',onChoose:()=>{chooseCompanion(state.player.activeCompanion==='lucien'?null:'lucien');closeDialogue()}},{text:'Terminer.',onChoose:closeDialogue}])}
