function v014TalkBastien(){const q=state.companionQuests.bastien;if(q.stage===0){openDialogue(speaker('Bastien Orris','NAVIGATEUR FRANC DU LARGE','BO'),'J’ai guidé des familles jusqu’au Frioul. Pour financer les traversées, j’ai signé des dettes au nom d’équipages qui ne savaient pas lire les contrats. Le registre est caché dans le bunker du port.',[{text:'Je récupérerai le registre.',onChoose:()=>{q.stage=1;closeDialogue();saveGame(false)}},{text:'Vous auriez dû leur dire la vérité.',onChoose:()=>{q.stage=1;state.companions.loyalty.bastien-=5;closeDialogue();saveGame(false)}},{text:'Pas maintenant.',onChoose:closeDialogue}]);return}if(q.stage===1)openDialogue(speaker('Bastien Orris','NAVIGATEUR FRANC DU LARGE','BO'),'Le registre se trouve au Port Dieudonné. Sans lui, les créanciers peuvent inventer n’importe quelle dette.',[{text:'Je pars pour le Frioul.',onChoose:closeDialogue}]);else if(q.stage===2)openDialogue(speaker('Bastien Orris','NAVIGATEUR FRANC DU LARGE','BO'),'Le registre est authentique. Que deviennent ces dettes ?', [{text:'Les annuler et publier les comptes.',onChoose:()=>v014RecruitBastien('cancel')},{text:'Les convertir en parts de la flotte commune.',onChoose:()=>v014RecruitBastien('shares')},{text:'Les vendre aux Francs contre la sécurité des routes.',onChoose:()=>v014RecruitBastien('sell')}]);else openDialogue(speaker('Bastien Orris','COMPAGNON RECRUTÉ','BO'),'Le vent tourne. Les cartes, elles, peuvent rester honnêtes.',[{text:state.player.activeCompanion==='bastien'?'Restez au port.':'Venez avec moi.',onChoose:()=>{chooseCompanion(state.player.activeCompanion==='bastien'?null:'bastien');closeDialogue()}},{text:'Terminer.',onChoose:closeDialogue}])}
