function v014TalkMarius(){const q=state.companionQuests.marius;if(q.stage===0){openDialogue(speaker('MARIUS-4','UNITÉ DE MAINTENANCE','M4'),'MÉMOIRE PARTIELLE. Ordres contradictoires : maintenir la production, protéger les ouvriers, effacer les interruptions. Un noyau mémoriel compatible peut être assemblé sur place.',[{text:'Réparer le noyau — circuits 3, pièces 2.',condition:()=>hasCost({circuitry:3,weaponParts:2}),lockText:'Circuits 3 et pièces d’arme 2 requis.',onChoose:()=>{payCost({circuitry:3,weaponParts:2});q.stage=2;v014TalkMarius()}},{text:'Recomposer la mémoire.',tag:conditionTag('I',7),condition:()=>state.character.special.I>=7,onChoose:()=>{q.stage=2;v014TalkMarius()}},{text:'Laisser l’unité en veille.',onChoose:closeDialogue}]);return}if(q.stage===2)openDialogue(speaker('MARIUS-4','UNITÉ DE MAINTENANCE','M4'),'Noyau restauré. Choisissez une politique mémorielle.',[{text:'Préserver toutes les mémoires et leurs contradictions.',onChoose:()=>v014RecruitMarius('preserve')},{text:'Créer une copie autonome avant réparation.',onChoose:()=>v014RecruitMarius('fork')},{text:'Réinitialiser les ordres de production.',onChoose:()=>v014RecruitMarius('reset')}]);else openDialogue(speaker('MARIUS-4','COMPAGNON RECRUTÉ','M4'),'MAINTENANCE DISPONIBLE. Consentement aux réparations confirmé.',[{text:state.player.activeCompanion==='marius'?'Retourner à la savonnerie.':'M’accompagner.',onChoose:()=>{chooseCompanion(state.player.activeCompanion==='marius'?null:'marius');closeDialogue()}},{text:'Terminer.',onChoose:closeDialogue}])}
