let constructionState=null;
function openConstruction(siteId){if(!V014_RECONSTRUCTION[siteId])return;constructionState={siteId};previousMode=mode;mode='CONSTRUCTION';document.exitPointerLock?.();$('constructionScreen').classList.remove('hidden');renderConstruction()}
function renderConstruction(){if(!constructionState)return;const site=V014_RECONSTRUCTION[constructionState.siteId],built=state.reconstruction.sites[constructionState.siteId]||{};$('constructionTitle').textContent=site.name.toUpperCase();$('constructionDesc').textContent='Chaque module apparaît immédiatement dans le secteur et participe à sa production lors des voyages.';$('constructionResources').innerHTML=['caps','scrap','circuitry','cloth','chemicals','weaponParts','ceramicFilter'].map(k=>`<span>${k==='caps'?'Capsules':itemLabel(k)} <b>${k==='caps'?state.player.caps:(state.inventory[k]||0)}</b></span>`).join('');$('constructionModules').innerHTML=Object.entries(site.modules).map(([id,m])=>`<article class="construction-module ${built[id]?'done':''}"><b>${escapeHtml(m.name)}</b><small>${escapeHtml(m.desc)}</small><em>${built[id]?'CONSTRUIT':costText(m.cost)}</em><button data-build="${id}" ${built[id]?'disabled':''}>${built[id]?'OPÉRATIONNEL':'CONSTRUIRE'}</button></article>`).join('');$('constructionModules').querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>buildReconstructionModule(constructionState.siteId,b.dataset.build));$('constructionClose').onclick=closeConstruction}
function buildReconstructionModule(siteId,moduleId){const def=V014_RECONSTRUCTION[siteId].modules[moduleId],built=state.reconstruction.sites[siteId];if(built[moduleId])return;if(!payCost(def.cost)){toast(`Ressources requises : ${costText(def.cost)}`,'bad');return}built[moduleId]=true;state.settlements[siteId]=Math.max(state.settlements[siteId]||0,Object.values(built).filter(Boolean).length);gainXP(45,'Reconstruction visible');achievement(`rebuild-${siteId}-${moduleId}`,`${def.name} construit`);audio.success();toast(`${def.name} apparaît dans le secteur.`,'good');saveGame(false);refreshWorld();renderConstruction()}
function closeConstruction(){$('constructionScreen').classList.add('hidden');constructionState=null;mode='PLAYING';setTimeout(()=>$('gameCanvas').requestPointerLock?.(),80)}
const v013ProductionForV014=grantNetworkProduction;grantNetworkProduction=function(){v013ProductionForV014();for(const [siteId,site] of Object.entries(V014_RECONSTRUCTION)){const built=state.reconstruction.sites[siteId]||{};for(const [id,on] of Object.entries(built)){if(!on)continue;for(const [item,n] of Object.entries(site.modules[id].output||{})){if(item==='caps')state.player.caps+=n;else if(isAmmo(item))state.ammo[item]=(state.ammo[item]||0)+n;else state.inventory[item]=(state.inventory[item]||0)+n}}}}

let petanqueState=null;
function openPetanque(){previousMode=mode;mode='PETANQUE';document.exitPointerLock?.();const wind=Math.round((world?.env?.wind||1)*8-4);petanqueState={round:1,wind,balls:[],best:999};$('petanqueScreen').classList.remove('hidden');renderPetanque()}
function renderPetanque(){if(!petanqueState)return;const angle=Number($('petanqueAngle').value||0),power=Number($('petanquePower').value||62);$('petanqueAngleOut').textContent=`${angle}°`;$('petanquePowerOut').textContent=`${power}%`;$('petanqueRound').textContent=`${petanqueState.round} / 3`;$('petanqueBest').textContent=petanqueState.best>=999?'—':`${petanqueState.best.toFixed(1)} cm`;$('petanqueWind').textContent=`${petanqueState.wind>0?'+':''}${petanqueState.wind} km/h`;$('petanqueAim').style.transform=`rotate(${angle}deg)`;$('petanqueBalls').innerHTML=petanqueState.balls.map(b=>`<i style="left:${b.x}%;top:${b.y}%"></i>`).join('');$('petanqueThrow').disabled=petanqueState.round>3;$('petanqueThrow').textContent=petanqueState.round>3?'PARTIE TERMINÉE':'LANCER LA BOULE'}
function throwPetanque(){if(!petanqueState||petanqueState.round>3)return;const angle=Number($('petanqueAngle').value),power=Number($('petanquePower').value),wind=petanqueState.wind,spread=(Math.sin((angle+wind*.7)*Math.PI/180)*18),distance=Math.abs(70-power*.78)+Math.abs(spread)*.55+((petanqueState.round*7)%9);const x=clamp(76+spread*.55,8,94),y=clamp(47+(70-power)*.45,8,92);petanqueState.balls.push({x,y,distance});petanqueState.best=Math.min(petanqueState.best,distance);petanqueState.round++;audio.tone(210,.08,'sine',.08,90);if(petanqueState.round>3){const finalBest=petanqueState.best;state.foundation.q12.played++;state.foundation.q12.best=state.foundation.q12.best==null?finalBest:Math.min(state.foundation.q12.best,finalBest);if(finalBest<=18){state.foundation.q12.wins++;state.foundation.q12.outcome='victoire';state.player.caps+=35;repChange('ligue',1);gainXP(60,'On joue encore');achievement('petanque-win','On joue encore')}else state.foundation.q12.outcome='participation';saveGame(false);setTimeout(()=>toast(finalBest<=18?'Partie gagnée. La place applaudit.':'Partie terminée. Jo vous invite à recommencer.',finalBest<=18?'good':''),300)}renderPetanque()}
function closePetanque(){$('petanqueScreen').classList.add('hidden');petanqueState=null;mode='PLAYING';setTimeout(()=>$('gameCanvas').requestPointerLock?.(),80)}

let lockpickState=null;
function openLockpick(id,opts={}){previousMode=mode;mode='LOCKPICK';document.exitPointerLock?.();const seed=detailHash(`LOCK-${id}`),target=(seed%151)-75;lockpickState={id,target,difficulty:opts.difficulty||2,reward:opts.reward||null,pins:state.inventory.bobbyPin||0};$('lockpickTitle').textContent=opts.title||'CAISSE VERROUILLÉE';$('lockpickScreen').classList.remove('hidden');renderLockpick()}
function renderLockpick(){if(!lockpickState)return;const angle=Number($('lockpickAngle').value||0),tol=Math.max(3,15-lockpickState.difficulty*2);$('lockpickPin').style.transform=`translateX(-50%) rotate(${angle}deg)`;$('lockpickPins').textContent=state.inventory.bobbyPin||0;$('lockpickTolerance').textContent=`${tol}°`;$('lockpickCylinder').style.transform='rotate(0deg)';$('lockpickMessage').textContent='Cherchez le point de résistance.'}
function turnLockpick(){if(!lockpickState)return;if((state.inventory.bobbyPin||0)<=0){toast('Aucune épingle.','bad');return}const angle=Number($('lockpickAngle').value),tol=Math.max(3,15-lockpickState.difficulty*2),delta=Math.abs(angle-lockpickState.target);if(delta<=tol){$('lockpickCylinder').style.transform='rotate(88deg)';state.collectibles.lockedCaches[lockpickState.id]=true;audio.success();const reward=lockpickState.reward;setTimeout(()=>{closeLockpick();reward?.();saveGame(false);refreshWorld()},320)}else{state.inventory.bobbyPin=Math.max(0,(state.inventory.bobbyPin||0)-1);$('lockpickMessage').textContent=angle<lockpickState.target?'La résistance vient de la droite.':'La résistance vient de la gauche.';audio.empty();renderLockpick()}}
