const v013RenderPipDataForV014=renderPipData;renderPipData=function(c){v013RenderPipDataForV014(c);const list=c.querySelector('.pip-list'),detail=c.querySelector('#dataDetail');if(!list||!detail)return;const addBtn=(id,label,handler)=>{const b=document.createElement('button');b.dataset.v14data=id;b.textContent=label;list.insertBefore(b,list.querySelector('[data-data="achievements"]'));b.onclick=()=>{list.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');handler()}};const done=V014_FOUNDATION_QUESTS.filter(x=>v014FoundationStatus(x[3])).length;addBtn('foundation',`PROMESSES INITIALES (${done}/12)`,()=>{detail.innerHTML=`<h3>POSTULAT DE BASE · ${done}/12</h3><p>Les douze quêtes fondatrices relient culture, travail, eau, transport, soins, littoral et moments de vie ordinaire.</p><div class="foundation-grid">${V014_FOUNDATION_QUESTS.map(([id,title,zone,key])=>{const outcome=v014FoundationStatus(key);return`<article class="foundation-card ${outcome?'done':''}"><small>${id.toUpperCase()} · ${escapeHtml(zone)}</small><h4>${escapeHtml(title)}</h4><p>${outcome?`Résolue · ${escapeHtml(String(outcome))}`:'À découvrir ou à terminer.'}</p></article>`}).join('')}</div>`});addBtn('companions',`ARCS DES COMPAGNONS (${['mireille','naima','emile','roux','lucien','bastien','marius'].filter(id=>state.flags[COMPANIONS[id].flag]).length}/7)`,()=>{detail.innerHTML=`<h3>COMPAGNONS FONDATEURS</h3><p>Chaque allié possède une provenance, une décision de recrutement et une utilité hors combat.</p>${Object.entries(COMPANIONS).map(([id,d])=>`<article class="companion-arc"><b>${escapeHtml(d.fullName)}</b> · ${state.flags[d.flag]?'RECRUTÉ':'NON RECRUTÉ'}<p>${escapeHtml(d.role)} · Loyauté ${state.companions.loyalty[id]||0}${state.companionQuests[id]?` · Arc ${state.companionQuests[id].stage}/3${state.companionQuests[id].outcome?` · ${state.companionQuests[id].outcome}`:''}`:''}</p></article>`).join('')}`});const mc=Object.keys(state.collectibles.magazines).length,pc=Object.keys(state.collectibles.plans).length;addBtn('collectibles',`COLLECTIONS (${mc+pc}/36)`,()=>{detail.innerHTML=`<h3>MAGAZINES & PLANS</h3><div class="collectible-progress"><article><b>Magazines ${mc}/18</b><small>Bonus permanents, culture et récits du territoire.</small></article><article><b>Plans ${pc}/18</b><small>Recettes disponibles aux établis avancés.</small></article><article><b>Caches ouvertes ${Object.keys(state.collectibles.lockedCaches).length}</b><small>Serrures mécaniques et cargaisons uniques.</small></article></div><h4>MAGAZINES</h4><div class="archive-grid">${V014_MAGAZINES.map(x=>`<article class="archive-card collectible-card ${state.collectibles.magazines[x[0]]?'done':'locked'}"><b>${state.collectibles.magazines[x[0]]?escapeHtml(x[1]):'PUBLICATION NON TROUVÉE'}</b><p>${state.collectibles.magazines[x[0]]?escapeHtml(x[3]):escapeHtml(DETAIL_ZONE_LABELS[x[2]]||x[2])}</p></article>`).join('')}</div><h4>PLANS</h4><div class="archive-grid">${V014_PLANS.map(x=>`<article class="archive-card ${state.collectibles.plans[x[0]]?'done':'locked'}"><b>${state.collectibles.plans[x[0]]?escapeHtml(x[1]):'PLAN NON TROUVÉ'}</b><p>${state.collectibles.plans[x[0]]?escapeHtml(V014_RECIPES[x[3]].name):escapeHtml(DETAIL_ZONE_LABELS[x[2]]||x[2])}</p></article>`).join('')}</div><button id="openRecipeBench">OUVRIR L’ÉTABLI DES PLANS</button>`;$('openRecipeBench').onclick=()=>{closePipboy();openRecipeBench()}})};

