function v016GroundPatch(w,x,z,sx,sz,color,y=.025,rot=0){addBox(w,[x,y,z],[sx,.05,sz],color,rot)}
function v016LocalBox(w,p,dx,dy,dz,sx,sy,sz,color,rot=0,opts={}){return addBox(w,[p[0]+dx,p[1]+dy,p[2]+dz],[sx,sy,sz],color,rot,opts)}
function v016PortalProtected(w,x,z,r=6.5){return Object.values(w.geoPortals||{}).some(p=>Math.hypot(x-p[0],z-p[2])<r)}
function v016ClearArea(w,p,r){
  const keep=d=>{if(!d?.pos)return true;const sx=d.scale?.[0]||0,sz=d.scale?.[2]||0;if(sx>70||sz>70||d.id?.startsWith('geo-ground')||v016PortalProtected(w,d.pos[0],d.pos[2]))return true;return Math.hypot(d.pos[0]-p[0],d.pos[2]-p[2])>r};
  w.staticDraws=w.staticDraws.filter(keep);w.colliders=w.colliders.filter(c=>{const x=(c.minX+c.maxX)/2,z=(c.minZ+c.maxZ)/2;return v016PortalProtected(w,x,z)||Math.hypot(x-p[0],z-p[2])>r});w.coverPoints=w.coverPoints.filter(c=>v016PortalProtected(w,c.pos[0],c.pos[2])||Math.hypot(c.pos[0]-p[0],c.pos[2]-p[2])>r)
}
function v016ClearCorridor(w,pts,r=3.8){
  const near=(x,z)=>pts.some(p=>Math.hypot(x-p[0],z-p[2])<r),keep=d=>{if(!d?.pos)return true;const sx=d.scale?.[0]||0,sz=d.scale?.[2]||0;if(sx>70||sz>70||d.id?.startsWith('geo-ground')||v016PortalProtected(w,d.pos[0],d.pos[2]))return true;return !near(d.pos[0],d.pos[2])};
  w.staticDraws=w.staticDraws.filter(keep);w.colliders=w.colliders.filter(c=>{const x=(c.minX+c.maxX)/2,z=(c.minZ+c.maxZ)/2;return v016PortalProtected(w,x,z)||!near(x,z)});w.coverPoints=w.coverPoints.filter(c=>v016PortalProtected(w,c.pos[0],c.pos[2])||!near(c.pos[0],c.pos[2]))
}
function v016AddRoute(w,a,b,kind,seed){
  const widths={arterial:4.1,street:2.9,road:2.45,service:1.75,trail:1.1,coast:2.15,industrial:3.2},width=widths[kind]||2.3,pts=v015CurvedPoints(a,b,seed,Math.max(10,Math.ceil(dist2(a,b)/10)));v016ClearCorridor(w,pts,width+1.7);
  const color=kind==='trail'?COLORS.dirt:kind==='coast'?cMix(COLORS.road,COLORS.limestone,.25):kind==='industrial'?cMix(COLORS.road,COLORS.rust,.22):COLORS.road;
  for(let i=0;i<pts.length-1;i++){
    v015SegmentBox(w,pts[i],pts[i+1],width,color,.045);
    const p=pts[i],q=pts[i+1],dx=q[0]-p[0],dz=q[2]-p[2],len=Math.hypot(dx,dz),nx=-dz/Math.max(.001,len),nz=dx/Math.max(.001,len);
    if(['arterial','street','road','coast'].includes(kind))for(const side of[-1,1])v015SegmentBox(w,[p[0]+nx*side*(width*.64),0,p[2]+nz*side*(width*.64)],[q[0]+nx*side*(width*.64),0,q[2]+nz*side*(width*.64)],kind==='coast'?.28:.38,kind==='coast'?COLORS.limestone:COLORS.concrete,.07);
    if(i%4===0){
      const side=i%8===0?-1:1,x=p[0]+nx*side*(width+1.2),z=p[2]+nz*side*(width+1.2);
      if(kind==='trail'){addRock(w,x,z,.45+((i%3)*.12),COLORS.limestone);if(i%8===0)addTree(w,x+1.2,z-.6,.42,'pine')}
      else if(kind==='coast'){addBarrier(w,x,z,2.8,Math.atan2(dx,dz));if(i%8===0)addRock(w,x+1.8,z,1.0,COLORS.limestone)}
      else if(kind==='industrial'){addBarrier(w,x,z,3.2,Math.atan2(dx,dz));if(i%8===0)addCrate(w,x+1.5,z,COLORS.rust)}
      else {addLamp(w,x,z,i%12!==0);if(i%8===0)addBenchProp(w,x+1.2,0,z+.8,Math.atan2(dx,dz),.75)}
    }
  }
  return pts
}
function v016AddSubzone(w,id,name,pos,type='surface',height=0){w.subzones.push({id:`v016-${id}-${w.subzones.length}`,name,pos:[pos[0],height,pos[2]],rot:0,type});return pos}
function v016AddSiteSign(w,p,color=COLORS.green){addPart(w,'cylinder',[p[0],1.1,p[2]],[.12,2.2,.12],COLORS.darkMetal);addBox(w,[p[0],2.15,p[2]],[3.7,.82,.18],COLORS.darkMetal);addBox(w,[p[0],2.15,p[2]-.11],[3.25,.48,.05],color,0,{emissive:.22})}
function v016AddLocalCache(w,id,p,kind){const item=kind.includes('coast')?'sealant':kind.includes('forest')?'fireGel':kind==='park'?'water':kind==='agricultural'?'food':'scrap',amount=item==='scrap'?3:1;addLoot(w,`v016-cache-${id}`,[p[0]+7,.6,p[2]-7],item,amount,`Réserve de ${V016_SURFACE_SITES[id].label}`)}
function v016SiteDialogue(id){
  const d=V016_SURFACE_SITES[id],done=state.geo.surfaceActions[id],visited=!!state.geo.surfaceVisited[id];if(!d)return talkAmbient();
  const choices=[];
  if(!visited)choices.push({text:'Consigner ce lieu sur la carte.',onChoose:()=>{state.geo.surfaceVisited[id]=true;state.geo.discoveryCount=Object.keys(state.geo.surfaceVisited).length;state.geo.lastSurface=id;gainXP(8,`Découverte · ${d.label}`);closeDialogue();saveGame(false)}});
  if(!done)choices.push({text:d.kind.includes('forest')?'Aider à dégager le coupe-feu.':d.kind.includes('coast')?'Renforcer le quai et les accès.':d.kind.includes('park')?'Remettre en état les allées et l’eau.':d.kind.includes('village')||d.kind==='town'?'Réparer la place et les passages.':'Soutenir les services locaux.',condition:()=>hasCost({scrap:2}),lockText:'Ferraille 2 requise.',onChoose:()=>{payCost({scrap:2});state.geo.surfaceActions[id]='restored';repChange(d.macro==='geo_laciotat'?'arsenal':d.macro==='geo_marseille'?'rade':'ligue',1);gainXP(18,`Restauration · ${d.label}`);closeDialogue();refreshWorld();saveGame(false)}});
  choices.push({text:'Demander l’état des routes.',onChoose:()=>openDialogue(speaker(d.npc[0],d.npc[1],d.npc[0].split(/\s+/).map(x=>x[0]).slice(0,2).join('')),d.lore,[{text:'Revenir à la conversation.',onChoose:()=>v016SiteDialogue(id)}])},{text:'Prendre congé.',onChoose:closeDialogue});
  openDialogue(speaker(d.npc[0],d.npc[1],d.npc[0].split(/\s+/).map(x=>x[0]).slice(0,2).join('')),done?`${d.lore} Les réparations locales ont rouvert un passage et stabilisé les services.`:d.lore,choices)
}

