/* ---------- Monde strict : contenu scénarisé conservé, géométrie réelle seule ---------- */
function v017AddPortalOnly(w,id,a){const p=v015GeoProject(w.id,a.lat,a.lon),color=SHELTER_DEFS[id]?COLORS.amber:COLORS.green,pending=state.geo?.pendingTarget===id;addPart(w,'cylinder',[p[0],1.15,p[2]],[.12,2.3,.12],COLORS.darkMetal);addBox(w,[p[0],2.45,p[2]],[4.6,.62,.18],COLORS.darkMetal);addBox(w,[p[0],2.45,p[2]-.11],[4.05,.35,.05],color,0,{emissive:.36});addInteract(w,`geo-portal-${id}`,[p[0],1.2,p[2]+1.8],`${pending?'OBJECTIF · ':''}Entrer : ${a.label}`,()=>v015EnterInstance(id),{radius:4.2,marker:pending,kind:'geo-portal',priority:.8});w.geoPortals[id]=[p[0],0,p[2]];w.subzones.push({id:`geo-${id}`,name:a.label,pos:[p[0],0,p[2]],rot:0,type:a.type||'portal'})}
function v017AddSurfaceContent(w,id,d){const p=v015GeoProject(w.id,d.lat,d.lon);v016AddSiteSign(w,[p[0],0,p[2]],d.kind.includes('coast')?COLORS.water:d.kind.includes('forest')?COLORS.olive2:COLORS.green);addHumanNPC(w,`v016-${id}`,d.npc[0],d.npc[1],[p[0]+2,0,p[2]+3],d.kind.includes('coast')?COLORS.clothBlue:COLORS.clothTan,{dialogue:`v016-site-${id}`});v016AddLocalCache(w,id,p,d.kind);addInteract(w,`v016-discovery-${id}`,[p[0],1.1,p[2]+6],state.geo.surfaceVisited[id]?`${d.label} · site consigné`:`Découvrir : ${d.label}`,()=>v016SiteDialogue(id),{radius:4,marker:!state.geo.surfaceVisited[id],kind:'surface-site',priority:.42});w.surfaceSites.push({id,label:d.label,kind:d.kind,pos:[p[0],0,p[2]],subzones:1,restored:state.geo.surfaceActions[id]==='restored'});w.subzones.push({id:`v017-site-${id}`,name:d.label,pos:[p[0],0,p[2]],rot:0,type:d.kind})}
function v017BuildGeoMacro(id){const d=V015_GEO_MACROS[id],env=d.kind==='islands'?{skyTop:[70,120,155],skyBottom:[182,177,142],fog:[.42,.60,.62],wind:1.7}:{skyTop:[78,126,154],skyBottom:[198,185,143],fog:[.55,.64,.59],wind:d.kind==='hills'?1.8:1.25},w=createWorld(id,d.name.replace('Territoire réel','Territoire cadastral'),d.region,env);w.geoMacro=true;w.geo={...d,id,attribution:V017_ATTRIBUTION,strict:true,source:'MVT'};w.geoPortals={};w.geoTiles=new Set();w.geoTileStats={};w.subzones=[];w.surfaceSites=[];w.surfaceRoutes=[];w.zoneLinks=[...d.neighbors];w.zoneGates=[];w.levelRoutes=[];w.bounds=v015MacroBounds(id);const[minX,maxX,minZ,maxZ]=w.bounds,wid=maxX-minX,dep=maxZ-minZ;w.spawn=[0,1.65,0];w.spawnYaw=0;addFloorZone(w,(minX+maxX)/2,(minZ+maxZ)/2,wid,dep,0,{id:`geo-ground-${id}`});addBox(w,[(minX+maxX)/2,-.34,(minZ+maxZ)/2],[wid,.66,dep],v015MacroThemeColor(d.kind),0,{id:`geo-ground-${id}`});
  for(const zoneId of v015MacroDestinations(id)){const a=v015AnchorForZone(zoneId);if(a)v017AddPortalOnly(w,zoneId,a)}
  for(const[sid,site]of Object.entries(V016_SURFACE_SITES))if(site.macro===id)v017AddSurfaceContent(w,sid,site);
  for(const[from,to,atId,targetId,label,index]of V016_MACRO_TRANSITIONS.map((v,i)=>[...v,i]))if(from===id){const a=v015AnchorForZone(atId),t=v015AnchorForZone(targetId);if(!a||!t)continue;const p=v015GeoProject(from,a.lat,a.lon),tp=v015GeoProject(to,t.lat,t.lon);addBox(w,[p[0]+4,1.5,p[2]+7],[1.1,3,.3],COLORS.darkMetal);addBox(w,[p[0]+4,3.15,p[2]+7],[5.2,.65,.22],COLORS.amber,0,{emissive:.3});addInteract(w,`v017-transition-${from}-${to}-${index}`,[p[0]+4,1,p[2]+8],label,()=>loadZone(to,{geoDirect:true,force:true,spawn:[tp[0],1.65,tp[2]+10]}),{radius:4,kind:'geo-bridge'});w.zoneLinks.push(to)}
  w.surfaceStats={sites:w.surfaceSites.length,subzones:w.surfaceSites.length,routes:0,routePoints:0,restored:w.surfaceSites.filter(s=>s.restored).length,draws:w.staticDraws.length,colliders:w.colliders.length};w.levelStats={subzones:w.subzones.length,links:w.zoneLinks.length,pathSegments:0,boundaryPieces:0,drawsAdded:w.staticDraws.length,closedLoops:0};w.cohesionStats={landmarks:w.subzones.length,edgeLayers:0,drawsAdded:w.staticDraws.length,interiors:0,verticalLoops:0};setTimeout(async()=>{if(world===w){await v017LoadTerrain(w);v017ScheduleAroundPlayer(w)}},0);return w}
v015BuildGeoMacro=v017BuildGeoMacro;

v015UpdateGeoStreaming=function(dt){if(!world?.geoMacro)return;V017_RUNTIME.lastCheck+=dt;if(V017_RUNTIME.lastCheck<.72)return;V017_RUNTIME.lastCheck=0;v017ScheduleAroundPlayer(world);v017PruneTiles(world)};

/* ---------- HUD et audit de fidélité ---------- */
function v017EnsureAuditPanel(){if($('geoAuditPanel'))return;const el=document.createElement('div');el.id='geoAuditPanel';el.className='geo-audit-panel hidden';el.innerHTML='<b>AUDIT CARTOGRAPHIQUE</b><span id="geoAuditTiles">—</span><span id="geoAuditBuildings">—</span><span id="geoAuditRoads">—</span><span id="geoAuditErrors">—</span>';document.querySelector('#hud')?.appendChild(el)}
function v017UpdateAuditPanel(){v017EnsureAuditPanel();const el=$('geoAuditPanel');if(!el)return;el.classList.toggle('hidden',!settings.geoAudit||!world?.geoMacro);if(el.classList.contains('hidden'))return;const a=V017_RUNTIME.audit;$('geoAuditTiles').textContent=`TUILES · FOND ${a.tilesBase} · CADASTRE ${a.tilesCadastre}`;$('geoAuditBuildings').textContent=`BÂTI · SOURCE ${a.sourceBuildings} · RENDU ${a.renderedBuildings}`;$('geoAuditRoads').textContent=`ROUTES · SOURCE ${a.sourceRoads} · SEGMENTS ${a.renderedRoads} · EXTRÉMITÉS ${a.danglingRoadEnds}`;$('geoAuditErrors').textContent=`PROCÉDURAL · 0 ROUTE / 0 MAISON · ERREURS ${a.tilesFailed}`}
const V017_HUD_BASE=v015UpdateGeoHud;
v015UpdateGeoHud=function(){v015EnsureGeoHud();const el=$('geoHud');if(!el)return;const active=!!world?.geoMacro;el.classList.toggle('hidden',!active);if(active){const n=v016NearestSite();$('geoMode').textContent=`TERRITOIRE CADASTRAL · ${(n&&n.distance<45?n.label:world.region.replace('MACRO-RÉGION · ','')).toUpperCase()}`;$('geoStream').textContent=`${V017_RUNTIME.status} · ${V017_RUNTIME.audit.tilesBase+V017_RUNTIME.audit.tilesCadastre} TUILE(S) · LOD ${settings.quality.toUpperCase()}`;el.querySelector('small').textContent=V017_ATTRIBUTION}v017UpdateAuditPanel()};

function v017RenderGeoMap(c){const anchors=Object.entries(V015_GEO_ANCHORS),sites=Object.entries(V016_SURFACE_SITES);let nodes=[...anchors,...sites].map(([id,a])=>{const[x,y]=v015MapXY(a.lat,a.lon),cur=world?.id===a.macro,cl=sites.some(([s])=>s===id)?'surface':'geo';return`<g data-geo-map="${id}" class="map-node ${cl} ${cur?'current':''}"><circle cx="${x}" cy="${y}" r="${cl==='surface'?4.2:6.2}"/><text x="${x+7}" y="${y-5}">${escapeHtml(a.label)}</text></g>`}).join('');for(const sid of SHELTER_IDS){const a=v015AnchorForZone(sid);if(!a)continue;const[x,y]=v015MapXY(a.lat,a.lon);nodes+=`<g data-geo-map="${sid}" class="map-node shelter"><circle cx="${x}" cy="${y}" r="3.8"/><text x="${x+5}" y="${y-4}">${escapeHtml(SHELTER_DEFS[sid].code)}</text></g>`}const macros=Object.entries(V015_GEO_MACROS).map(([id,d])=>{const[x,y]=v015MapXY(d.center[0],d.center[1]);return`<text class="macro-label" x="${x}" y="${y-24}">${escapeHtml(d.region.replace('MACRO-RÉGION · ',''))}</text>`}).join('');const a=V017_RUNTIME.audit;c.innerHTML=`<div class="pip-map geo-map v017"><svg viewBox="0 0 1850 840" role="img" aria-label="Atlas cadastral Marseille Aubagne La Ciotat"><path class="geo-sea" d="${v015CoastPath()}"/>${macros}${nodes}<text x="28" y="818" class="geo-attribution">${escapeHtml(V017_ATTRIBUTION)}</text></svg><div class="geo-map-legend"><b>ATLAS CADASTRAL DU TERRITOIRE COMPLET</b><span>8 macro-régions · données vectorielles chargées à la demande sur tout le périmètre.</span><span>Bâtiments source/rendus : ${a.sourceBuildings}/${a.renderedBuildings} · routes source : ${a.sourceRoads} · aucune maison ou route procédurale.</span><span class="geo-status-inline">${escapeHtml(V017_RUNTIME.status)}</span></div></div>`;c.querySelectorAll('[data-geo-map]').forEach(n=>n.addEventListener('click',()=>{const id=n.dataset.geoMap;if(inCombat){toast('Impossible de voyager pendant un combat.','bad');return}closePipboy();loadZone(id)}))}
v015RenderGeoPipMap=v017RenderGeoMap;renderPipMap=function(c){v017RenderGeoMap(c)};

const V017_SYNC_OPTIONS_BASE=syncOptionsUI;
