/* ---------- Fixture QA MVT : prouve le décodeur sans prétendre être une carte réelle ---------- */
function v017ApplyDecodedFixture(source,z,x,y,buffer){if(!world?.geoMacro)return false;V017_RUNTIME.fixtureMode=true;V017_RUNTIME.status='FIXTURE QA · PAS UNE DONNÉE RÉELLE';const key=`${source}:fixture:${z}:${x}:${y}`;const layers=v017DecodeMVT(buffer);if(source==='cadastre')return v017ApplyCadastreTile(world,key,layers,z,x,y,'fixture');return v017ApplyFranceTile(world,key,layers,z,x,y,'fixture')}
function v017MapPackPlan(){const plans={base:new Set(),cadastre:new Set()};for(const d of Object.values(V015_GEO_MACROS)){for(const source of['base','cadastre']){const z=V017_TILE_SOURCES[source].zoom,a=v017LonLatToTile(d.bbox[2],d.bbox[1],z),b=v017LonLatToTile(d.bbox[0],d.bbox[3],z);for(let x=Math.floor(Math.min(a.x,b.x));x<=Math.floor(Math.max(a.x,b.x));x++)for(let y=Math.floor(Math.min(a.y,b.y));y<=Math.floor(Math.max(a.y,b.y));y++)plans[source].add(`${z}/${x}/${y}`)}}return{base:[...plans.base],cadastre:[...plans.cadastre],counts:{base:plans.base.size,cadastre:plans.cadastre.size,total:plans.base.size+plans.cadastre.size}}}

Object.assign(window.__MISTRAL_DEBUG,{
  v017Sources:()=>deepClone(V017_TILE_SOURCES),v017Status:()=>({status:V017_RUNTIME.status,source:V017_RUNTIME.source,lastError:V017_RUNTIME.lastError,pending:V017_RUNTIME.pending.size,queue:V017_RUNTIME.queue.length,loaded:V017_RUNTIME.loaded.size,errors:V017_RUNTIME.errors.size,audit:deepClone(V017_RUNTIME.audit)}),
  v017DecodeMVT:(arr)=>{const u=arr instanceof Uint8Array?arr:new Uint8Array(arr);const layers=v017DecodeMVT(u);return Object.fromEntries(Object.entries(layers).map(([k,l])=>[k,{features:l.features.length,extent:l.extent,types:[...new Set(l.features.map(f=>f.type))]}]))},
  v017ApplyFixture:(source,z,x,y,arr)=>v017ApplyDecodedFixture(source,z,x,y,new Uint8Array(arr)),v017PackPlan:()=>v017MapPackPlan(),v017ClearCache:()=>v017CacheClear(),
  v017Audit:()=>deepClone(V017_RUNTIME.audit),v017WorldAudit:()=>({id:world?.id,strict:!!world?.geo?.strict,draws:world?.staticDraws?.length||0,polygons:world?.staticDraws?.filter(d=>['prism','flatpoly'].includes(d.mesh)).length||0,polyColliders:world?.colliders?.filter(c=>c.poly).length||0,proceduralBuildings:V017_RUNTIME.audit.proceduralBuildings,proceduralRoads:V017_RUNTIME.audit.proceduralRoads,tiles:[...(world?.geoTiles||[])]}),
  v017LoadMacro:(id='geo_marseille')=>{V017_RUNTIME.fixtureMode=false;gameStarted=true;loadZone(id,{silent:true,geoDirect:true,force:true,spawn:[0,1.65,0]});mode='PLAYING';$('hud').classList.add('active');return id},v017LoadInstance:(id='canebiere')=>{V017_RUNTIME.fixtureMode=false;gameStarted=true;v015LoadZoneForV016(id,{silent:true,force:true});mode='PLAYING';$('hud').classList.add('active');return id},v017SetPlayerLatLon:(lat,lon,yaw=0,pitch=0)=>{if(!world?.geoMacro)return null;const p=v015GeoProject(world.id,lat,lon);state.player.pos=[p[0],v017TerrainHeight(world,p[0],p[2])+playerEyeHeight(),p[2]];state.player.yaw=yaw;state.player.pitch=pitch;return[...state.player.pos]},v017SetAudit:(v=true)=>{settings.geoAudit=!!v;v017UpdateAuditPanel();return settings.geoAudit},v017Schedule:()=>{if(world?.geoMacro)v017ScheduleAroundPlayer(world);return V017_RUNTIME.queue.length}
});


/* ---------- Relief IGN optionnel : grilles générées par build_terrain_pack.py ---------- */
function v017TerrainHeight(w,x,z){const t=w?.geoTerrain;if(!t)return 0;const [minX,maxX,minZ,maxZ]=w.bounds,u=clamp((x-minX)/Math.max(.001,maxX-minX),0,1),v=clamp((z-minZ)/Math.max(.001,maxZ-minZ),0,1),gx=u*(t.width-1),gz=v*(t.height-1),x0=Math.floor(gx),z0=Math.floor(gz),x1=Math.min(t.width-1,x0+1),z1=Math.min(t.height-1,z0+1),tx=gx-x0,tz=gz-z0,at=(xx,zz)=>t.heights[zz*t.width+xx]||0,a=lerp(at(x0,z0),at(x1,z0),tx),b=lerp(at(x0,z1),at(x1,z1),tx);return lerp(a,b,tz)}
const V017_GROUND_BASE=groundHeightAt;
groundHeightAt=function(x,z,currentGround=0){if(world?.geoMacro&&world.geoTerrain)return v017TerrainHeight(world,x,z);return V017_GROUND_BASE(x,z,currentGround)};
const V017_SEGMENT_BASE=v015SegmentBox;
v015SegmentBox=function(w,a,b,width,color,y=.035,tag=null){if(w?.geoTerrain)y+=(v017TerrainHeight(w,a[0],a[2])+v017TerrainHeight(w,b[0],b[2]))*.5;return V017_SEGMENT_BASE(w,a,b,width,color,y,tag)};
const V017_PRISM_BASE=v017AddPrism;
v017AddPrism=function(w,rings,baseY,height,color,opts={}){if(w?.geoTerrain&&baseY===0){const b=v017PolyBounds(rings);baseY=v017TerrainHeight(w,b.cx,b.cz)}return V017_PRISM_BASE(w,rings,baseY,height,color,opts)};
const V017_FLATPOLY_BASE=v017AddFlatPoly;
v017AddFlatPoly=function(w,rings,y,color,opts={}){if(w?.geoTerrain){const b=v017PolyBounds(rings);y+=v017TerrainHeight(w,b.cx,b.cz)}return V017_FLATPOLY_BASE(w,rings,y,color,opts)};

const V017_DRAW_POLY_BASE=SoftwareRenderer.prototype.drawItem;
SoftwareRenderer.prototype.drawItem=function(d,z,camera,basis,focal,env){if(d.mesh!=='terrain')return V017_DRAW_POLY_BASE.call(this,d,z,camera,basis,focal,env);const ctx=this.ctx,faces=[];for(const f of d.faces){const pts=f.map(i=>this.projectPoint(d.vertices[i],camera,basis,focal));if(pts.some(p=>!p))continue;const avg=pts.reduce((n,p)=>n+p.z,0)/pts.length;if(avg>280)continue;faces.push({pts,avg})}faces.sort((a,b)=>b.avg-a.avg);for(const f of faces){ctx.fillStyle=this.color(d.color,f.avg,env,.9,d.alpha??1);ctx.beginPath();f.pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fill()} };
function v017AddTerrainMesh(w,t){const quality=settings.quality,n=quality==='high'?34:quality==='medium'?26:18,[minX,maxX,minZ,maxZ]=w.bounds,verts=[],faces=[];for(let iz=0;iz<n;iz++)for(let ix=0;ix<n;ix++){const x=lerp(minX,maxX,ix/(n-1)),z=lerp(minZ,maxZ,iz/(n-1));verts.push([x,v017TerrainHeight(w,x,z)-.05,z])}for(let iz=0;iz<n-1;iz++)for(let ix=0;ix<n-1;ix++){const a=iz*n+ix,b=a+1,c=a+n,d=c+1;faces.push([a,c,b],[b,c,d])}const col=w.geo.kind==='coast'||w.geo.kind==='islands'?cMix(COLORS.limestone,COLORS.olive,.17):w.geo.kind==='urban'?cMix(COLORS.concrete,COLORS.dirt,.44):cMix(COLORS.dirt,COLORS.olive,.18);w.staticDraws.unshift({mesh:'terrain',pos:[(minX+maxX)/2,(t.min+t.max)*.5,(minZ+maxZ)/2],vertices:verts,faces,color:col,alpha:1,scale:[1,1,1],rotY:0,id:`terrain-${w.id}`})}
function v017GroundExistingContent(w){for(const d of w.staticDraws){if(d.mesh==='terrain'||d.id===`geo-ground-${w.id}`||d.v017Grounded||d.geoTile)continue;const h=v017TerrainHeight(w,d.pos[0],d.pos[2]);d.pos[1]+=h;d.v017Grounded=true}for(const it of w.interactables){if(it.v017Grounded)continue;it.pos[1]+=v017TerrainHeight(w,it.pos[0],it.pos[2]);it.v017Grounded=true}for(const n of w.npcs){const h=v017TerrainHeight(w,n.pos[0],n.pos[2]);n.pos[1]+=h;if(n.home)n.home[1]+=h;if(n.route)for(const p of n.route)p[1]=v017TerrainHeight(w,p[0],p[2]);}for(const l of w.loot)l.pos[1]+=v017TerrainHeight(w,l.pos[0],l.pos[2]);for(const s of w.subzones)s.pos[1]=v017TerrainHeight(w,s.pos[0],s.pos[2]);state.player.pos[1]=v017TerrainHeight(w,state.player.pos[0],state.player.pos[2])+playerEyeHeight()}
async function v017LoadTerrain(w){if(!w?.geoMacro||location.protocol==='file:'){w.geoTerrainStatus='ABSENT · importer un MNT IGN pour le relief exact';return false}try{const r=await fetch(`data/map_pack/terrain/${w.id}.json`,{cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);const j=await r.json(),scale=V015_GEO_MACROS[w.id].scale,vals=Array.isArray(j.values)?j.values:[];if(vals.length!==j.width*j.height)throw new Error('grille incomplète');const min=Number(j.min)||0;w.geoTerrain={width:j.width,height:j.height,heights:vals.map(v=>(Number(v)-min)*scale),absoluteMin:min,min:0,max:((Number(j.max)||min)-min)*scale,source:'IGN/RGE ALTI local'};w.staticDraws=w.staticDraws.filter(d=>d.id!==`geo-ground-${w.id}`);v017AddTerrainMesh(w,w.geoTerrain);v017GroundExistingContent(w);w.geoTerrainStatus=`RELIEF LOCAL · ${Math.round(j.min)}–${Math.round(j.max)} M`;V017_RUNTIME.status='RELIEF ET CARTOGRAPHIE LOCALE';return true}catch(e){w.geoTerrainStatus='RELIEF NON CHARGÉ · SOL PLAN, AUCUN RELIEF INVENTÉ';return false}}
Object.assign(window.__MISTRAL_DEBUG,{v017Terrain:()=>world?.geoTerrain?{width:world.geoTerrain.width,height:world.geoTerrain.height,min:world.geoTerrain.absoluteMin,max:world.geoTerrain.absoluteMin+world.geoTerrain.max/V015_GEO_MACROS[world.id].scale,source:world.geoTerrain.source}:null,v017TerrainHeight:(x,z)=>v017TerrainHeight(world,x,z)});

